(function(){
"use strict";
// Generated in the user's code style; assembled by Lab.tsScript in ts-core.js.
Lab.ts({
"geo-raysphere":{"k":"S","what":"A bubble shield made of pure maths: a scanner's ray is tested against the sphere with the quadratic formula (no part needed for the hit test).","services":[],"variables":"","functions":"local function RaySphere(origin, direction, sphereCenter, sphereRadius)\n\tlocal fromCenter = origin - sphereCenter\n\tlocal halfB = fromCenter:Dot(direction)\n\tlocal discriminant = halfB * halfB - (fromCenter:Dot(fromCenter) - sphereRadius * sphereRadius)\n\tif discriminant < 0 then return nil end\n\tlocal hitDistance = -halfB - math.sqrt(discriminant)\n\treturn hitDistance > 0 and hitDistance or nil\nend","setup":"local center, radius = ORIGIN + Vector3.new(0, 5, -6), 5\n\nMakePart(Vector3.new(radius * 2, radius * 2, radius * 2), center, Color3.fromRGB(90, 160, 255), {\n\tShape = Enum.PartType.Ball,\n\tTransparency = 0.75,\n\tCanCollide = false,\n\tCanQuery = false,\n\tMaterial = Enum.Material.ForceField,\n})\n\nlocal scanner = MakePart(Vector3.new(1, 1, 2), ORIGIN + Vector3.new(0, 5, 14), Color3.fromRGB(60, 60, 70))\nlocal beam = MakeLinePart(Color3.fromRGB(255, 60, 60))\n\nlocal hitDot = MakePart(\n\tVector3.new(0.8, 0.8, 0.8),\n\tcenter,\n\tColor3.fromRGB(250, 200, 40),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false, CanQuery = false }\n)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tlocal direction = (Vector3.new(math.sin(now) * 9, math.cos(now * 0.7) * 5, -20)).Unit\n\tlocal hit = RaySphere(scanner.Position, direction, center, radius)\n\tlocal endPoint = scanner.Position + direction * (hit or 40)\n\tDrawLine(beam, scanner.Position, endPoint)\n\thitDot.Transparency = hit and 0 or 1\n\thitDot.Position = endPoint\nend)"},
"geo-rayplane":{"k":"L","what":"Move your mouse: a ray from the camera is intersected with an invisible floor 6 studs up (ray vs plane), and a block follows that spot.","services":["UserInputService"],"variables":"","functions":"local function RayPlane(origin, direction, point, normal)\n\tlocal denominator = direction:Dot(normal)\n\tif math.abs(denominator) < 1e-6 then return nil end\n\tlocal distance = (point - origin):Dot(normal) / denominator\n\tif distance < 0 then return nil end\n\treturn origin + direction * distance\nend","setup":"local PLANE_POINT, NORMAL = Vector3.new(0, 6, 0), Vector3.yAxis\n\nlocal block = MakePart(\n\tVector3.new(2, 2, 2),\n\tORIGIN,\n\tColor3.fromRGB(226, 133, 26),\n\t{ CanCollide = false, CanQuery = false, Transparency = 0.3 }\n)","runtime":"runService.RenderStepped:Connect(function()\n\tlocal mouse = userInputService:GetMouseLocation()\n\tlocal ray = camera:ViewportPointToRay(mouse.X, mouse.Y)\n\tlocal hit = RayPlane(ray.Origin, ray.Direction, PLANE_POINT, NORMAL)\n\tblock.Transparency = hit and 0.3 or 1\n\tif hit then\n\t\tblock.Position = Vector3.new(math.round(hit.X / 2) * 2, hit.Y + 1, math.round(hit.Z / 2) * 2)\n\tend\nend)"},
"geo-polygon":{"k":"S","what":"An irregular zone marked by neon edges. They turn green while any player stands inside (even-odd crossing test).","services":[],"variables":"","functions":"local function IsInside(point, polygon)\n\tlocal inside, previousIndex = false, #polygon\n\tfor i = 1, #polygon do\n\t\tlocal cornerA, cornerB = polygon[i], polygon[previousIndex]\n\t\tif\n\t\t\t(cornerA.Y > point.Y) ~= (cornerB.Y > point.Y)\n\t\t\tand point.X\n\t\t\t\t< cornerA.X + (point.Y - cornerA.Y) * (cornerB.X - cornerA.X) / (cornerB.Y - cornerA.Y)\n\t\tthen\n\t\t\tinside = not inside\n\t\tend\n\t\tpreviousIndex = i\n\tend\n\treturn inside\nend","setup":"local ZONE = {\n\tVector2.new(-14, -10),\n\tVector2.new(-2, -12),\n\tVector2.new(4, -4),\n\tVector2.new(14, -10),\n\tVector2.new(12, 8),\n\tVector2.new(0, 2),\n\tVector2.new(-10, 10),\n}\n\nlocal edges = {}\n\nfor i, cornerA in ZONE do\n\tlocal cornerB = ZONE[i % #ZONE + 1]\n\tlocal edge = MakeLinePart(Color3.fromRGB(230, 80, 80))\n\tDrawLine(\n\t\tedge,\n\t\tORIGIN + Vector3.new(cornerA.X, 0.3, cornerA.Y),\n\t\tORIGIN + Vector3.new(cornerB.X, 0.3, cornerB.Y)\n\t)\n\tedges[i] = edge\nend","runtime":"runService.Heartbeat:Connect(function()\n\tlocal anyone = false\n\tfor _, player in players:GetPlayers() do\n\t\tlocal root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\t\tif root then\n\t\t\tlocal offset = root.Position - ORIGIN\n\t\t\tanyone = anyone or IsInside(Vector2.new(offset.X, offset.Z), ZONE)\n\t\tend\n\tend\n\tfor _, edgeLine in edges do\n\t\tedgeLine.Color = anyone and Color3.fromRGB(60, 220, 100) or Color3.fromRGB(230, 80, 80)\n\tend\nend)"},
"geo-segments":{"k":"S","what":"A laser fence between two posts. If a player's movement between two frames crosses it (2D segment intersection), the fence flashes and prints who crossed.","services":[],"variables":"","functions":"local function Cross2D(vectorA, vectorB)\n\treturn vectorA.X * vectorB.Y - vectorA.Y * vectorB.X\nend\n\nlocal function SegmentsCross(startA, directionA, startB, directionB)\n\tlocal denominator = Cross2D(directionA, directionB)\n\tif math.abs(denominator) < 1e-9 then return false end\n\tlocal alongA, alongB =\n\t\tCross2D(startB - startA, directionB) / denominator, Cross2D(startB - startA, directionA) / denominator\n\treturn alongA >= 0 and alongA <= 1 and alongB >= 0 and alongB <= 1\nend","setup":"local FENCE_START, FENCE_END = Vector2.new(-12, -4), Vector2.new(12, 4)\n\nMakePart(\n\tVector3.new(1, 5, 1),\n\tORIGIN + Vector3.new(FENCE_START.X, 2.5, FENCE_START.Y),\n\tColor3.fromRGB(60, 60, 70)\n)\n\nMakePart(\n\tVector3.new(1, 5, 1),\n\tORIGIN + Vector3.new(FENCE_END.X, 2.5, FENCE_END.Y),\n\tColor3.fromRGB(60, 60, 70)\n)\n\nlocal laser = MakeLinePart(Color3.fromRGB(255, 60, 60))\n\nDrawLine(\n\tlaser,\n\tORIGIN + Vector3.new(FENCE_START.X, 3, FENCE_START.Y),\n\tORIGIN + Vector3.new(FENCE_END.X, 3, FENCE_END.Y)\n)\n\nlocal lastPosition = {}","runtime":"runService.Heartbeat:Connect(function()\n\tfor _, player in players:GetPlayers() do\n\t\tlocal root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\t\tif root then\n\t\t\tlocal now = Vector2.new(root.Position.X - ORIGIN.X, root.Position.Z - ORIGIN.Z)\n\t\t\tif\n\t\t\t\tlastPosition[player]\n\t\t\t\tand SegmentsCross(\n\t\t\t\t\tFENCE_START,\n\t\t\t\t\tFENCE_END - FENCE_START,\n\t\t\t\t\tlastPosition[player],\n\t\t\t\t\tnow - lastPosition[player]\n\t\t\t\t)\n\t\t\tthen\n\t\t\t\tprint(player.Name .. \" crossed the laser!\")\n\t\t\t\tlaser.Color = Color3.fromRGB(255, 255, 255)\n\t\t\t\ttask.delay(0.2, function()\n\t\t\t\t\tlaser.Color = Color3.fromRGB(255, 60, 60)\n\t\t\t\tend)\n\t\t\tend\n\t\t\tlastPosition[player] = now\n\t\tend\n\tend\nend)"},
"ik-cosines":{"k":"S","what":"Three posts form a triangle that changes shape; the angle at each corner is worked out from the three side lengths (law of cosines).","services":[],"variables":"","functions":"local function AngleOpposite(opposite, sideOne, sideTwo)\n\treturn math.acos(math.clamp((sideOne ^ 2 + sideTwo ^ 2 - opposite ^ 2) / (2 * sideOne * sideTwo), -1, 1))\nend","setup":"local cornerA =\n\tMakePart(Vector3.new(1, 1, 1), ORIGIN, Color3.fromRGB(217, 54, 62), { Shape = Enum.PartType.Ball })\n\nlocal cornerB =\n\tMakePart(Vector3.new(1, 1, 1), ORIGIN, Color3.fromRGB(46, 158, 82), { Shape = Enum.PartType.Ball })\n\nlocal cornerC =\n\tMakePart(Vector3.new(1, 1, 1), ORIGIN, Color3.fromRGB(47, 111, 214), { Shape = Enum.PartType.Ball })\n\nlocal sideAB, sideBC, sideCA = MakeLinePart(), MakeLinePart(), MakeLinePart()\nlocal labelA, labelB, labelC = MakeLabel(cornerA), MakeLabel(cornerB), MakeLabel(cornerC)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tlocal positionA, positionB = ORIGIN + Vector3.new(-8, 2, 0), ORIGIN + Vector3.new(8, 2, 0)\n\tlocal positionC = ORIGIN + Vector3.new(math.sin(now * 0.5) * 6, 2 + 6 + math.sin(now) * 3, 0)\n\tcornerA.Position, cornerB.Position, cornerC.Position = positionA, positionB, positionC\n\tDrawLine(sideAB, positionA, positionB)\n\tDrawLine(sideBC, positionB, positionC)\n\tDrawLine(sideCA, positionC, positionA)\n\tlocal lengthA, lengthB, lengthC =\n\t\t(positionB - positionC).Magnitude,\n\t\t(positionA - positionC).Magnitude,\n\t\t(positionA - positionB).Magnitude\n\tlabelA.Text = string.format(\"A %.0f\", math.deg(AngleOpposite(lengthA, lengthB, lengthC)))\n\tlabelB.Text = string.format(\"B %.0f\", math.deg(AngleOpposite(lengthB, lengthA, lengthC)))\n\tlabelC.Text = string.format(\"C %.0f\", math.deg(AngleOpposite(lengthC, lengthA, lengthB)))\nend)"},
"ik-twobone":{"k":"S","what":"A two-bone arm on a pedestal reaches toward the nearest player (or an orbiting point), with the elbow bending upward toward a pole.","services":[],"variables":"local _upperLength = 6\nlocal _lowerLength = 5","functions":"local function Solve(shoulder, target, pole)\n\tlocal toTarget = target - shoulder\n\tlocal reach = math.clamp(\n\t\ttoTarget.Magnitude,\n\t\tmath.abs(_upperLength - _lowerLength) + 0.01,\n\t\t_upperLength + _lowerLength - 0.01\n\t)\n\tlocal direction = toTarget.Unit\n\tlocal shoulderAngle = math.acos(\n\t\tmath.clamp(\n\t\t\t(_upperLength * _upperLength + reach * reach - _lowerLength * _lowerLength)\n\t\t\t\t/ (2 * _upperLength * reach),\n\t\t\t-1,\n\t\t\t1\n\t\t)\n\t)\n\tlocal toPole = pole - shoulder\n\tlocal bend = toPole - direction * toPole:Dot(direction)\n\tbend = bend.Magnitude > 1e-3 and bend.Unit or Vector3.yAxis\n\treturn shoulder\n\t\t+ direction * (math.cos(shoulderAngle) * _upperLength)\n\t\t+ bend * (math.sin(shoulderAngle) * _upperLength),\n\t\tshoulder + direction * reach\nend","setup":"local SHOULDER = ORIGIN + Vector3.new(0, 8, 0)\nMakePart(Vector3.new(3, 8, 3), SHOULDER - Vector3.new(0, 4, 0), Color3.fromRGB(80, 80, 90))\n\nlocal upper = MakePart(\n\tVector3.new(0.8, 0.8, _upperLength),\n\tSHOULDER,\n\tColor3.fromRGB(70, 130, 240),\n\t{ CanCollide = false }\n)\n\nlocal lower = MakePart(\n\tVector3.new(0.7, 0.7, _lowerLength),\n\tSHOULDER,\n\tColor3.fromRGB(230, 100, 160),\n\t{ CanCollide = false }\n)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tlocal root = GetNearestRoot(SHOULDER, 25)\n\tlocal target = root and root.Position\n\t\tor SHOULDER + Vector3.new(math.cos(now) * 7, math.sin(now * 1.3) * 3, math.sin(now) * 7)\n\tlocal elbow, hand = Solve(SHOULDER, target, SHOULDER + Vector3.new(0, 10, 0))\n\tupper.CFrame = CFrame.lookAt((SHOULDER + elbow) / 2, elbow)\n\tlower.CFrame = CFrame.lookAt((elbow + hand) / 2, hand)\nend)"},
"ik-fabrik":{"k":"S","what":"A 10-segment tentacle reaches for the nearest player (or a wandering point) using FABRIK: drag the tip to the target, then drag the base back, a few times per frame.","services":[],"variables":"local _segments = 10\nlocal _length = 1.3\nlocal _passes = 3","functions":"","setup":"local BASE = ORIGIN + Vector3.new(0, 0.5, 0)\nlocal points, segments = {}, {}\n\nfor i = 0, _segments do\n\tpoints[i] = BASE + Vector3.new(0, i * _length, 0)\nend\n\nfor i = 1, _segments do\n\tsegments[i] = MakePart(\n\t\tVector3.new(0.8 - i * 0.05, 0.8 - i * 0.05, _length),\n\t\tBASE,\n\t\tColor3.fromHSV(0.8 + i * 0.01, 0.6, 0.9),\n\t\t{ CanCollide = false }\n\t)\nend","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tlocal root = GetNearestRoot(BASE, 20)\n\tlocal target = root and root.Position\n\t\tor BASE\n\t\t\t+ Vector3.new(math.sin(now * 0.7) * 8, 6 + math.sin(now * 1.3) * 3, math.cos(now * 0.7) * 6)\n\tfor _ = 1, _passes do\n\t\tpoints[_segments] = target\n\t\tfor i = _segments - 1, 0, -1 do\n\t\t\tpoints[i] = points[i + 1] + (points[i] - points[i + 1]).Unit * _length\n\t\tend\n\t\tpoints[0] = BASE\n\t\tfor i = 0, _segments - 1 do\n\t\t\tpoints[i + 1] = points[i] + (points[i + 1] - points[i]).Unit * _length\n\t\tend\n\tend\n\tfor i = 1, _segments do\n\t\tsegments[i].CFrame = CFrame.lookAt((points[i - 1] + points[i]) / 2, points[i])\n\tend\nend)"},
"ph-integrators":{"k":"S","what":"Three balls orbit a sun with the same start but different update rules. Explicit Euler spirals outward; semi-implicit Euler and Verlet stay on orbit.","services":[],"variables":"local _gravityStrength = 400 -- a big time step makes the difference obvious\nlocal _timeStep = 1 / 20","functions":"","setup":"local SUN = ORIGIN + Vector3.new(0, 8, 0)\n\nMakePart(\n\tVector3.new(3, 3, 3),\n\tSUN,\n\tColor3.fromRGB(255, 200, 60),\n\t{ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon }\n)\n\nlocal function GravityAt(position)\n\tlocal offset = SUN - position\n\treturn offset * (_gravityStrength / offset.Magnitude ^ 3)\nend\n\nlocal kinds = { \"explicit Euler\", \"semi-implicit Euler\", \"velocity Verlet\" }\nlocal bodies = {}\n\nlocal function Reset()\n\tfor i, name in kinds do\n\t\tlocal startPosition, startVelocity =\n\t\t\tSUN + Vector3.new(10, 0, 0), Vector3.new(0, 0, -math.sqrt(_gravityStrength / 10))\n\t\tif not bodies[i] then\n\t\t\tbodies[i] = {\n\t\t\t\tPart = MakePart(\n\t\t\t\t\tVector3.new(1, 1, 1),\n\t\t\t\t\tstartPosition,\n\t\t\t\t\tColor3.fromHSV(i / 4, 0.7, 1),\n\t\t\t\t\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n\t\t\t\t),\n\t\t\t}\n\t\t\tMakeLabel(bodies[i].Part, name)\n\t\tend\n\t\tbodies[i].P, bodies[i].V = startPosition, startVelocity\n\tend\nend\n\nReset()\nlocal accumulator, elapsed = 0, 0","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\taccumulator += deltaTime\n\twhile accumulator >= _timeStep do\n\t\taccumulator -= _timeStep\n\t\telapsed += _timeStep\n\t\tlocal euler, semiImplicit, verlet = bodies[1], bodies[2], bodies[3]\n\t\tlocal acceleration = GravityAt(euler.Position)\n\t\teuler.Position += euler.Velocity * _timeStep\n\t\teuler.Velocity += acceleration * _timeStep -- explicit\n\t\tsemiImplicit.Velocity += GravityAt(semiImplicit.Position) * _timeStep\n\t\tsemiImplicit.Position += semiImplicit.Velocity * _timeStep -- semi-implicit\n\t\tlocal accelerationBefore = GravityAt(verlet.Position)\n\t\tverlet.Position += verlet.Velocity * _timeStep + accelerationBefore * (0.5 * _timeStep * _timeStep)\n\t\tverlet.Velocity += (accelerationBefore + GravityAt(verlet.Position)) * (0.5 * _timeStep) -- Verlet\n\t\tif elapsed > 25 or (euler.Position - SUN).Magnitude > 40 then\n\t\t\tReset()\n\t\t\telapsed = 0\n\t\tend\n\tend\n\tfor _, body in bodies do\n\t\tbody.Part.Position = body.Position\n\tend\nend)"},
"ph-bounce":{"k":"S","what":"Balls drop onto a tilted ramp and bounce with your own physics: split velocity along the normal, flip it × restitution, reduce the sliding part with friction.","services":[],"variables":"","functions":"","setup":"local RESTITUTION, FRICTION, GRAVITY = 0.7, 0.2, Vector3.new(0, -60, 0)\nlocal tilt = math.rad(20)\nlocal normal = Vector3.new(math.sin(tilt), math.cos(tilt), 0)\nlocal planePoint = ORIGIN + Vector3.new(0, 2, 0)\nlocal ramp = MakePart(Vector3.new(30, 0.6, 8), planePoint, Color3.fromRGB(90, 90, 100))\nramp.CFrame = CFrame.new(planePoint - normal * 0.3) * CFrame.Angles(0, 0, -tilt)","runtime":"while true do\n\tlocal ball = MakePart(\n\t\tVector3.new(1.6, 1.6, 1.6),\n\t\tORIGIN + Vector3.new(-8, 16, math.random(-2, 2)),\n\t\tColor3.fromHSV(math.random(), 0.7, 1),\n\t\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n\t)\n\ttask.spawn(function()\n\t\tlocal position, velocity = ball.Position, Vector3.new(3, 0, 0)\n\t\tlocal start = os.clock()\n\t\twhile os.clock() - start < 6 do\n\t\t\tlocal deltaTime = runService.Heartbeat:Wait()\n\t\t\tvelocity += GRAVITY * deltaTime\n\t\t\tposition += velocity * deltaTime\n\t\t\tlocal depth = (position - planePoint):Dot(normal) - 0.8\n\t\t\tif depth < 0 then\n\t\t\t\tposition -= normal * depth\n\t\t\t\tlocal normalSpeed = velocity:Dot(normal)\n\t\t\t\tif normalSpeed < 0 then\n\t\t\t\t\tlocal normalPart = normal * normalSpeed\n\t\t\t\t\tlocal slidePart = velocity - normalPart\n\t\t\t\t\tlocal slide = slidePart.Magnitude\n\t\t\t\t\tif slide > 0 then\n\t\t\t\t\t\tslidePart *= math.max(\n\t\t\t\t\t\t\t0,\n\t\t\t\t\t\t\t1 - FRICTION * (1 + RESTITUTION) * math.abs(normalSpeed) / slide\n\t\t\t\t\t\t)\n\t\t\t\t\tend\n\t\t\t\t\tvelocity = slidePart - normalPart * RESTITUTION\n\t\t\t\tend\n\t\t\tend\n\t\t\tball.Position = position\n\t\tend\n\t\tball:Destroy()\n\tend)\n\ttask.wait(1.5)\nend"},
"ph-collide":{"k":"S","what":"A light ball hits a heavy one. The impulse along the line between them changes each velocity by its mass, and momentum is kept.","services":[],"variables":"local _restitution = 0.9","functions":"local function NewBall(mass, position, velocity, color)\n\tlocal radius = 0.8 * mass ^ (1 / 3)\n\treturn {\n\t\tMass = mass,\n\t\tRadius = radius,\n\t\tPosition = position,\n\t\tVelocity = velocity,\n\t\tPart = MakePart(\n\t\t\tVector3.new(radius * 2, radius * 2, radius * 2),\n\t\t\tposition,\n\t\t\tcolor,\n\t\t\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n\t\t),\n\t}\nend","setup":"","runtime":"while true do\n\tlocal ballA =\n\t\tNewBall(1, ORIGIN + Vector3.new(-14, 1, 0.6), Vector3.new(10, 0, 0), Color3.fromRGB(18, 147, 154))\n\tlocal ballB = NewBall(4, ORIGIN + Vector3.new(0, 1.6, 0), Vector3.zero, Color3.fromRGB(194, 65, 142))\n\tlocal label = MakeLabel(ballB.Part)\n\tlocal start = os.clock()\n\twhile os.clock() - start < 4 do\n\t\tlocal deltaTime = runService.Heartbeat:Wait()\n\t\tballA.Position += ballA.Velocity * deltaTime\n\t\tballB.Position += ballB.Velocity * deltaTime\n\t\tlocal offset = (ballB.Position - ballA.Position) * Vector3.new(1, 0, 1)\n\t\tlocal distance = offset.Magnitude\n\t\tif distance < ballA.Radius + ballB.Radius and distance > 0 then\n\t\t\tlocal normal = offset / distance\n\t\t\tlocal approaching = (ballA.Velocity - ballB.Velocity):Dot(normal)\n\t\t\tif approaching > 0 then\n\t\t\t\tlocal impulse = (1 + _restitution) * approaching / (1 / ballA.Mass + 1 / ballB.Mass)\n\t\t\t\tballA.Velocity -= normal * (impulse / ballA.Mass)\n\t\t\t\tballB.Velocity += normal * (impulse / ballB.Mass)\n\t\t\tend\n\t\tend\n\t\tballA.Part.Position, ballB.Part.Position = ballA.Position, ballB.Position\n\t\tlocal momentum = ballA.Velocity * ballA.Mass + ballB.Velocity * ballB.Mass\n\t\tlabel.Text = string.format(\"momentum (%.1f, %.1f)\", momentum.X, momentum.Z)\n\tend\n\tballA.Part:Destroy()\n\tballB.Part:Destroy()\nend"},
"ph-rope":{"k":"S","what":"A rope bridge between two posts simulated with Verlet points and distance constraints; it sags and sways in the wind.","services":[],"variables":"local _segments = 20\nlocal _passes = 10","functions":"","setup":"local LEFT_ANCHOR, RIGHT_ANCHOR = ORIGIN + Vector3.new(-12, 10, 0), ORIGIN + Vector3.new(12, 10, 0)\nMakePart(Vector3.new(1, 10, 1), LEFT_ANCHOR - Vector3.new(0, 5, 0), Color3.fromRGB(80, 60, 40))\nMakePart(Vector3.new(1, 10, 1), RIGHT_ANCHOR - Vector3.new(0, 5, 0), Color3.fromRGB(80, 60, 40))\nlocal SEGMENT_LENGTH = (RIGHT_ANCHOR - LEFT_ANCHOR).Magnitude * 1.15 / _segments\nlocal points, previous, planks = {}, {}, {}\n\nfor i = 0, _segments do\n\tpoints[i] = LEFT_ANCHOR:Lerp(RIGHT_ANCHOR, i / _segments)\n\tprevious[i] = points[i]\nend\n\nfor i = 1, _segments do\n\tplanks[i] = MakePart(\n\t\tVector3.new(2.5, 0.3, SEGMENT_LENGTH),\n\t\tLEFT_ANCHOR,\n\t\tColor3.fromRGB(150, 110, 70),\n\t\t{ CanCollide = false }\n\t)\nend\n\nlocal STEP, accumulator = 1 / 60, 0","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\taccumulator += math.min(deltaTime, 0.1)\n\twhile accumulator >= STEP do\n\t\taccumulator -= STEP\n\t\tlocal now = os.clock()\n\t\tlocal wind = Vector3.new(0, 0, math.sin(now * 0.8) * 15)\n\t\tfor i = 1, _segments - 1 do\n\t\t\tlocal velocity = (points[i] - previous[i]) * 0.99\n\t\t\tprevious[i] = points[i]\n\t\t\tpoints[i] += velocity + (Vector3.new(0, -60, 0) + wind) * STEP * STEP\n\t\tend\n\t\tfor _ = 1, _passes do\n\t\t\tpoints[0], points[_segments] = LEFT_ANCHOR, RIGHT_ANCHOR\n\t\t\tfor i = 0, _segments - 1 do\n\t\t\t\tlocal delta = points[i + 1] - points[i]\n\t\t\t\tlocal correction = delta\n\t\t\t\t\t* ((delta.Magnitude - SEGMENT_LENGTH) / math.max(delta.Magnitude, 1e-4))\n\t\t\t\t\t* 0.5\n\t\t\t\tif i > 0 then\n\t\t\t\t\tpoints[i] += correction\n\t\t\t\tend\n\t\t\t\tif i + 1 < _segments then\n\t\t\t\t\tpoints[i + 1] -= correction\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\tfor i = 1, _segments do\n\t\tplanks[i].CFrame = CFrame.lookAt((points[i - 1] + points[i]) / 2, points[i])\n\tend\nend)"},
"pg-fbm":{"k":"S","what":"Generates terrain from 5 octaves of layered noise (fBm) and colours it by height.","services":[],"variables":"local _size = 32\nlocal _cell = 2","functions":"local function HeightColor(height)\n\tif height < 0.32 then\n\t\treturn Color3.fromRGB(47, 111, 214)\n\telseif height < 0.37 then\n\t\treturn Color3.fromRGB(228, 209, 154)\n\telseif height < 0.62 then\n\t\treturn Color3.fromRGB(95, 174, 79)\n\telseif height < 0.8 then\n\t\treturn Color3.fromRGB(130, 130, 130)\n\tend\n\treturn Color3.fromRGB(242, 242, 242)\nend\n\nlocal function FractalNoise(x, z, octaves, seed)\n\tlocal amplitude, frequency, total, totalAmplitude = 1, 1, 0, 0\n\tfor i = 1, octaves do\n\t\ttotal += amplitude * math.noise(x * frequency, z * frequency, seed + i * 17.3)\n\t\ttotalAmplitude += amplitude\n\t\tamplitude *= 0.5\n\t\tfrequency *= 2\n\tend\n\treturn total / totalAmplitude\nend","setup":"local folder = Instance.new(\"Folder\")\nfolder.Parent = demoFolder\n\nlocal function BuildTerrain(heightAt) -- heightAt(x, z) returns 0..1\n\tfor x = 1, _size do\n\t\tfor z = 1, _size do\n\t\t\tlocal height = math.clamp(heightAt(x, z), 0, 1)\n\t\t\tlocal columnHeight = math.max(0.4, height * 20)\n\t\t\tMakePart(\n\t\t\t\tVector3.new(_cell, columnHeight, _cell),\n\t\t\t\tORIGIN + Vector3.new((x - _size / 2) * _cell, columnHeight / 2, (z - _size / 2) * _cell),\n\t\t\t\tHeightColor(height),\n\t\t\t\t{ Parent = folder }\n\t\t\t)\n\t\tend\n\t\ttask.wait()\n\tend\nend\n\nBuildTerrain(function(x, z)\n\treturn 0.5 + 1.2 * FractalNoise(x * 0.06 + 0.31, z * 0.06 + 0.47, 5, 4)\nend)","runtime":""},
"pg-ridged":{"k":"S","what":"Generates ridged mountains (1 − |noise|, squared) cut into flat terraces.","services":[],"variables":"local _size = 32\nlocal _cell = 2\nlocal _steps = 6","functions":"local function HeightColor(height)\n\tif height < 0.32 then\n\t\treturn Color3.fromRGB(47, 111, 214)\n\telseif height < 0.37 then\n\t\treturn Color3.fromRGB(228, 209, 154)\n\telseif height < 0.62 then\n\t\treturn Color3.fromRGB(95, 174, 79)\n\telseif height < 0.8 then\n\t\treturn Color3.fromRGB(130, 130, 130)\n\tend\n\treturn Color3.fromRGB(242, 242, 242)\nend\n\nlocal function FractalNoise(x, z, octaves, seed)\n\tlocal amplitude, frequency, total, totalAmplitude = 1, 1, 0, 0\n\tfor i = 1, octaves do\n\t\ttotal += amplitude * math.noise(x * frequency, z * frequency, seed + i * 17.3)\n\t\ttotalAmplitude += amplitude\n\t\tamplitude *= 0.5\n\t\tfrequency *= 2\n\tend\n\treturn total / totalAmplitude\nend","setup":"local folder = Instance.new(\"Folder\")\nfolder.Parent = demoFolder\n\nlocal function BuildTerrain(heightAt) -- heightAt(x, z) returns 0..1\n\tfor x = 1, _size do\n\t\tfor z = 1, _size do\n\t\t\tlocal height = math.clamp(heightAt(x, z), 0, 1)\n\t\t\tlocal columnHeight = math.max(0.4, height * 20)\n\t\t\tMakePart(\n\t\t\t\tVector3.new(_cell, columnHeight, _cell),\n\t\t\t\tORIGIN + Vector3.new((x - _size / 2) * _cell, columnHeight / 2, (z - _size / 2) * _cell),\n\t\t\t\tHeightColor(height),\n\t\t\t\t{ Parent = folder }\n\t\t\t)\n\t\tend\n\t\ttask.wait()\n\tend\nend\n\nBuildTerrain(function(x, z)\n\tlocal total, amplitude, frequency, totalAmplitude = 0, 1, 1, 0\n\tfor i = 1, 4 do\n\t\tlocal noise = math.clamp(\n\t\t\tmath.noise(x * 0.06 * frequency + 0.3, z * 0.06 * frequency + 0.7, 5 + i * 11) * 1.6,\n\t\t\t-1,\n\t\t\t1\n\t\t)\n\t\ttotal += amplitude * (1 - math.abs(noise)) ^ 2\n\t\ttotalAmplitude += amplitude\n\t\tamplitude *= 0.5\n\t\tfrequency *= 2\n\tend\n\treturn math.floor(total / totalAmplitude * _steps) / _steps -- terraces\nend)","runtime":""},
"pg-warp":{"k":"S","what":"Generates swirly, eroded-looking terrain by nudging each sample point with another noise first (domain warping).","services":[],"variables":"local _size = 32\nlocal _cell = 2\nlocal _warpStrength = 2.5","functions":"local function HeightColor(height)\n\tif height < 0.32 then\n\t\treturn Color3.fromRGB(47, 111, 214)\n\telseif height < 0.37 then\n\t\treturn Color3.fromRGB(228, 209, 154)\n\telseif height < 0.62 then\n\t\treturn Color3.fromRGB(95, 174, 79)\n\telseif height < 0.8 then\n\t\treturn Color3.fromRGB(130, 130, 130)\n\tend\n\treturn Color3.fromRGB(242, 242, 242)\nend\n\nlocal function FractalNoise(x, z, octaves, seed)\n\tlocal amplitude, frequency, total, totalAmplitude = 1, 1, 0, 0\n\tfor i = 1, octaves do\n\t\ttotal += amplitude * math.noise(x * frequency, z * frequency, seed + i * 17.3)\n\t\ttotalAmplitude += amplitude\n\t\tamplitude *= 0.5\n\t\tfrequency *= 2\n\tend\n\treturn total / totalAmplitude\nend","setup":"local folder = Instance.new(\"Folder\")\nfolder.Parent = demoFolder\n\nlocal function BuildTerrain(heightAt) -- heightAt(x, z) returns 0..1\n\tfor x = 1, _size do\n\t\tfor z = 1, _size do\n\t\t\tlocal height = math.clamp(heightAt(x, z), 0, 1)\n\t\t\tlocal columnHeight = math.max(0.4, height * 20)\n\t\t\tMakePart(\n\t\t\t\tVector3.new(_cell, columnHeight, _cell),\n\t\t\t\tORIGIN + Vector3.new((x - _size / 2) * _cell, columnHeight / 2, (z - _size / 2) * _cell),\n\t\t\t\tHeightColor(height),\n\t\t\t\t{ Parent = folder }\n\t\t\t)\n\t\tend\n\t\ttask.wait()\n\tend\nend\n\nBuildTerrain(function(x, z)\n\tlocal warpX = math.noise(x * 0.05 + 0.1, z * 0.05 + 0.2, 1) * _warpStrength\n\tlocal warpZ = math.noise(x * 0.05 + 0.5, z * 0.05 + 0.9, 2) * _warpStrength\n\treturn 0.5 + 1.2 * FractalNoise(x * 0.06 + warpX + 0.31, z * 0.06 + warpZ + 0.47, 4, 2)\nend)","runtime":""},
"pg-voronoi":{"k":"S","what":"A 40 × 40 floor split into 12 Voronoi regions: each tile takes the colour of its nearest seed.","services":[],"variables":"local _size = 40\nlocal _cell = 1","functions":"","setup":"local random = Random.new(8)\nlocal seeds = {}\n\nfor i = 1, 12 do\n\tseeds[i] = {\n\t\tPosition = Vector2.new(random:NextNumber(0, _size), random:NextNumber(0, _size)),\n\t\tColor = Color3.fromHSV(i * 0.618 % 1, 0.55, 0.9),\n\t}\nend\n\nfor x = 1, _size do\n\tfor z = 1, _size do\n\t\tlocal point = Vector2.new(x, z)\n\t\tlocal best, nearest, secondNearest = seeds[1], math.huge, math.huge\n\t\tfor _, seed in seeds do\n\t\t\tlocal distance = (point - seed.Position).Magnitude\n\t\t\tif distance < nearest then\n\t\t\t\tsecondNearest, nearest, best = nearest, distance, seed\n\t\t\telseif distance < secondNearest then\n\t\t\t\tsecondNearest = distance\n\t\t\tend\n\t\tend\n\t\tMakePart(\n\t\t\tVector3.new(_cell, 0.4, _cell),\n\t\t\tORIGIN + Vector3.new(x - _size / 2, 0.2, z - _size / 2),\n\t\t\tsecondNearest - nearest < 1 and Color3.fromRGB(40, 40, 45) or best.Color\n\t\t) -- dark tiles on the borders\n\tend\n\ttask.wait()\nend","runtime":""},
"pg-poisson":{"k":"S","what":"Plants up to 150 trees that are never closer than 4 studs to each other (Poisson disc by rejection).","services":[],"variables":"local _minDistance = 4\nlocal _target = 150","functions":"","setup":"local random = Random.new()\nlocal trees = {}\n\nfor _ = 1, _target * 40 do\n\tif #trees >= _target then break end\n\tlocal candidate = Vector2.new(random:NextNumber(-30, 30), random:NextNumber(-30, 30))\n\tlocal farEnough = true\n\tfor _, tree in trees do\n\t\tif (tree - candidate).Magnitude < _minDistance then\n\t\t\tfarEnough = false\n\t\t\tbreak\n\t\tend\n\tend\n\tif farEnough then\n\t\ttable.insert(trees, candidate)\n\t\tMakePart(\n\t\t\tVector3.new(0.8, 3, 0.8),\n\t\t\tORIGIN + Vector3.new(candidate.X, 1.5, candidate.Y),\n\t\t\tColor3.fromRGB(110, 80, 50)\n\t\t)\n\t\tMakePart(\n\t\t\tVector3.new(3, 3, 3),\n\t\t\tORIGIN + Vector3.new(candidate.X, 4, candidate.Y),\n\t\t\tColor3.fromRGB(60, 150, 70),\n\t\t\t{ Shape = Enum.PartType.Ball }\n\t\t)\n\tend\nend\n\nprint(#trees, \"trees placed\")","runtime":""},
"pg-caves":{"k":"S","what":"Generates a cave map: random walls, then 4 smoothing passes where a cell becomes wall if 5+ neighbours are walls.","services":[],"variables":"local _w = 48\nlocal _h = 36\nlocal _fill = 0.46","functions":"","setup":"local random = Random.new()\nlocal grid = {}\n\nfor x = 1, _w do\n\tgrid[x] = {}\n\tfor z = 1, _h do\n\t\tgrid[x][z] = x == 1 or z == 1 or x == _w or z == _h or random:NextNumber() < _fill\n\tend\nend\n\nfor _ = 1, 4 do\n\tlocal nextGrid = {}\n\tfor x = 1, _w do\n\t\tnextGrid[x] = {}\n\t\tfor z = 1, _h do\n\t\t\tlocal walls = 0\n\t\t\tfor offsetX = -1, 1 do\n\t\t\t\tfor offsetZ = -1, 1 do\n\t\t\t\t\tif\n\t\t\t\t\t\t(offsetX ~= 0 or offsetZ ~= 0)\n\t\t\t\t\t\tand (not grid[x + offsetX] or grid[x + offsetX][z + offsetZ] ~= false)\n\t\t\t\t\tthen\n\t\t\t\t\t\twalls += 1\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\t\tnextGrid[x][z] = walls >= 5 or (walls >= 4 and grid[x][z])\n\t\tend\n\tend\n\tgrid = nextGrid\nend\n\nfor x = 1, _w do\n\tfor z = 1, _h do\n\t\tif grid[x][z] then\n\t\t\tMakePart(\n\t\t\t\tVector3.new(1, 4, 1),\n\t\t\t\tORIGIN + Vector3.new(x - _w / 2, 2, z - _h / 2),\n\t\t\t\tColor3.fromRGB(90, 85, 80)\n\t\t\t)\n\t\tend\n\tend\n\ttask.wait()\nend","runtime":""},
"pg-walk":{"k":"S","what":"Carves a cave with a random walk: 1500 random steps from the centre, building a floor tile wherever the digger has been.","services":[],"variables":"local _steps = 1500","functions":"","setup":"local random = Random.new()\nlocal visited = {}\nlocal x, z = 0, 0\nlocal DIRECTIONS = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }\n\nfor _ = 1, _steps do\n\tlocal key = x .. \",\" .. z\n\tif not visited[key] then\n\t\tvisited[key] = true\n\t\tMakePart(Vector3.new(1, 0.4, 1), ORIGIN + Vector3.new(x, 0.2, z), Color3.fromRGB(226, 133, 26))\n\tend\n\tlocal direction = DIRECTIONS[random:NextInteger(1, 4)]\n\tx = math.clamp(x + direction[1], -25, 25)\n\tz = math.clamp(z + direction[2], -25, 25)\nend","runtime":""},
"pg-island":{"k":"S","what":"Generates an island: layered noise multiplied by a round falloff mask, so the land always ends in a beach.","services":[],"variables":"local _size = 32\nlocal _cell = 2","functions":"local function HeightColor(height)\n\tif height < 0.32 then\n\t\treturn Color3.fromRGB(47, 111, 214)\n\telseif height < 0.37 then\n\t\treturn Color3.fromRGB(228, 209, 154)\n\telseif height < 0.62 then\n\t\treturn Color3.fromRGB(95, 174, 79)\n\telseif height < 0.8 then\n\t\treturn Color3.fromRGB(130, 130, 130)\n\tend\n\treturn Color3.fromRGB(242, 242, 242)\nend\n\nlocal function FractalNoise(x, z, octaves, seed)\n\tlocal amplitude, frequency, total, totalAmplitude = 1, 1, 0, 0\n\tfor i = 1, octaves do\n\t\ttotal += amplitude * math.noise(x * frequency, z * frequency, seed + i * 17.3)\n\t\ttotalAmplitude += amplitude\n\t\tamplitude *= 0.5\n\t\tfrequency *= 2\n\tend\n\treturn total / totalAmplitude\nend","setup":"local folder = Instance.new(\"Folder\")\nfolder.Parent = demoFolder\n\nlocal function BuildTerrain(heightAt) -- heightAt(x, z) returns 0..1\n\tfor x = 1, _size do\n\t\tfor z = 1, _size do\n\t\t\tlocal height = math.clamp(heightAt(x, z), 0, 1)\n\t\t\tlocal columnHeight = math.max(0.4, height * 20)\n\t\t\tMakePart(\n\t\t\t\tVector3.new(_cell, columnHeight, _cell),\n\t\t\t\tORIGIN + Vector3.new((x - _size / 2) * _cell, columnHeight / 2, (z - _size / 2) * _cell),\n\t\t\t\tHeightColor(height),\n\t\t\t\t{ Parent = folder }\n\t\t\t)\n\t\tend\n\t\ttask.wait()\n\tend\nend\n\nBuildTerrain(function(x, z)\n\tlocal normalizedX, normalizedZ = (x - _size / 2) / (_size / 2), (z - _size / 2) / (_size / 2)\n\tlocal mask = math.clamp(1 - math.sqrt(normalizedX * normalizedX + normalizedZ * normalizedZ) ^ 2, 0, 1)\n\treturn (0.5 + 1.2 * FractalNoise(x * 0.08 + 0.31, z * 0.08 + 0.47, 4, 11)) * mask\nend)","runtime":""},
"pg-lsystem":{"k":"S","what":"Grows a bush from the L-system rule F → F[+F]F[−F]F, drawn with parts by a turtle that turns and branches.","services":[],"variables":"","functions":"","setup":"local RULE, ITERATIONS, ANGLE, LENGTH = \"F[+F]F[-F]F\", 3, math.rad(25.7), 1.2\nlocal sentence = \"F\"\n\nfor _ = 1, ITERATIONS do\n\tsentence = sentence:gsub(\"F\", RULE)\nend\n\nlocal position, angle, stack = ORIGIN, math.rad(90), {}\n\nfor symbol in sentence:gmatch(\".\") do\n\tif symbol == \"F\" then\n\t\tlocal nextPos = position + Vector3.new(math.cos(angle), math.sin(angle), 0) * LENGTH\n\t\tlocal branch = MakePart(Vector3.new(0.25, 0.25, LENGTH), position, Color3.fromRGB(90, 140, 60))\n\t\tbranch.CFrame = CFrame.lookAt((position + nextPos) / 2, nextPos)\n\t\tposition = nextPos\n\telseif symbol == \"+\" then\n\t\tangle += ANGLE\n\telseif symbol == \"-\" then\n\t\tangle -= ANGLE\n\telseif symbol == \"[\" then\n\t\ttable.insert(stack, { position, angle })\n\telseif symbol == \"]\" then\n\t\tposition, angle = table.unpack(table.remove(stack))\n\tend\nend","runtime":""},
"pf-bfs":{"k":"S","what":"Builds a small maze and runs breadth-first search from one corner to the other, colouring cells as they are explored, then shows the path.","services":[],"variables":"local _width = 18\nlocal _height = 14\nlocal _cell = 3","functions":"local function CellKey(x, z)\n\treturn x * 1000 + z\nend\n\nlocal function CellPosition(x, z)\n\treturn ORIGIN + Vector3.new((x - _width / 2) * _cell, 0, (z - _height / 2) * _cell)\nend\n\nlocal function ShowPath(path, color)\n\tfor _, cell in path do\n\t\tMakePart(\n\t\t\tVector3.new(1, 0.4, 1),\n\t\t\tCellPosition(cell[1], cell[2]) + Vector3.new(0, 0.4, 0),\n\t\t\tcolor or Color3.fromRGB(226, 133, 26),\n\t\t\t{ CanCollide = false }\n\t\t)\n\tend\nend","setup":"local walls = {}\nlocal random = Random.new(7)\n\nfor x = 1, _width do\n\tfor z = 1, _height do\n\t\tMakePart(\n\t\t\tVector3.new(_cell - 0.2, 0.2, _cell - 0.2),\n\t\t\tCellPosition(x, z) + Vector3.new(0, 0.1, 0),\n\t\t\tColor3.fromRGB(200, 200, 205)\n\t\t)\n\t\tif\n\t\t\trandom:NextNumber() < 0.22\n\t\t\tand not (x <= 2 and z <= 2)\n\t\t\tand not (x >= _width - 1 and z >= _height - 1)\n\t\tthen\n\t\t\twalls[CellKey(x, z)] = true\n\t\t\tMakePart(\n\t\t\t\tVector3.new(_cell, 3, _cell),\n\t\t\t\tCellPosition(x, z) + Vector3.new(0, 1.5, 0),\n\t\t\t\tColor3.fromRGB(50, 50, 60)\n\t\t\t)\n\t\tend\n\tend\nend\n\nlocal function IsOpen(x, z)\n\treturn x >= 1 and x <= _width and z >= 1 and z <= _height and not walls[CellKey(x, z)]\nend\n\nlocal function Neighbours(x, z)\n\tlocal list = {}\n\tfor _, direction in { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } } do\n\t\tif IsOpen(x + direction[1], z + direction[2]) then\n\t\t\ttable.insert(list, { x + direction[1], z + direction[2] })\n\t\tend\n\tend\n\treturn list\nend\n\nlocal start, goal = { 1, 1 }, { _width, _height }\nlocal cameFrom = { [CellKey(1, 1)] = false }\nlocal queue, head = { start }, 1\n\nwhile head <= #queue do\n\tlocal cell = queue[head]\n\thead += 1\n\tif cell[1] == goal[1] and cell[2] == goal[2] then break end\n\tMakePart(\n\t\tVector3.new(_cell - 0.6, 0.3, _cell - 0.6),\n\t\tCellPosition(cell[1], cell[2]) + Vector3.new(0, 0.25, 0),\n\t\tColor3.fromHSV(0.5 + head / 600, 0.5, 0.9),\n\t\t{ CanCollide = false }\n\t)\n\tfor _, neighbour in Neighbours(cell[1], cell[2]) do\n\t\tif cameFrom[CellKey(neighbour[1], neighbour[2])] == nil then\n\t\t\tcameFrom[CellKey(neighbour[1], neighbour[2])] = cell\n\t\t\ttable.insert(queue, neighbour)\n\t\tend\n\tend\n\ttask.wait(0.01)\nend\n\nlocal path, cell = {}, cameFrom[CellKey(goal[1], goal[2])] ~= nil and goal or nil\n\nwhile cell do\n\ttable.insert(path, 1, cell)\n\tcell = cameFrom[CellKey(cell[1], cell[2])]\nend\n\nShowPath(path)\nprint(#path > 0 and (#path - 1 .. \" steps\") or \"no path\")","runtime":""},
"pf-dijkstra":{"k":"S","what":"Dijkstra with costs: mud cells (brown) cost 5. The path detours around mud instead of taking the fewest steps.","services":[],"variables":"local _width = 18\nlocal _height = 14\nlocal _cell = 3","functions":"local function CellKey(x, z)\n\treturn x * 1000 + z\nend\n\nlocal function CellPosition(x, z)\n\treturn ORIGIN + Vector3.new((x - _width / 2) * _cell, 0, (z - _height / 2) * _cell)\nend\n\nlocal function ShowPath(path, color)\n\tfor _, cell in path do\n\t\tMakePart(\n\t\t\tVector3.new(1, 0.4, 1),\n\t\t\tCellPosition(cell[1], cell[2]) + Vector3.new(0, 0.4, 0),\n\t\t\tcolor or Color3.fromRGB(226, 133, 26),\n\t\t\t{ CanCollide = false }\n\t\t)\n\tend\nend","setup":"local walls = {}\nlocal random = Random.new(7)\n\nfor x = 1, _width do\n\tfor z = 1, _height do\n\t\tMakePart(\n\t\t\tVector3.new(_cell - 0.2, 0.2, _cell - 0.2),\n\t\t\tCellPosition(x, z) + Vector3.new(0, 0.1, 0),\n\t\t\tColor3.fromRGB(200, 200, 205)\n\t\t)\n\t\tif\n\t\t\trandom:NextNumber() < 0.22\n\t\t\tand not (x <= 2 and z <= 2)\n\t\t\tand not (x >= _width - 1 and z >= _height - 1)\n\t\tthen\n\t\t\twalls[CellKey(x, z)] = true\n\t\t\tMakePart(\n\t\t\t\tVector3.new(_cell, 3, _cell),\n\t\t\t\tCellPosition(x, z) + Vector3.new(0, 1.5, 0),\n\t\t\t\tColor3.fromRGB(50, 50, 60)\n\t\t\t)\n\t\tend\n\tend\nend\n\nlocal function IsOpen(x, z)\n\treturn x >= 1 and x <= _width and z >= 1 and z <= _height and not walls[CellKey(x, z)]\nend\n\nlocal function Neighbours(x, z)\n\tlocal list = {}\n\tfor _, direction in { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } } do\n\t\tif IsOpen(x + direction[1], z + direction[2]) then\n\t\t\ttable.insert(list, { x + direction[1], z + direction[2] })\n\t\tend\n\tend\n\treturn list\nend\n\nlocal mud = {}\n\nfor x = 1, _width do\n\tfor z = 1, _height do\n\t\tif IsOpen(x, z) and math.noise(x * 0.25, z * 0.25, 3) > 0.1 then\n\t\t\tmud[CellKey(x, z)] = true\n\t\t\tMakePart(\n\t\t\t\tVector3.new(_cell - 0.2, 0.25, _cell - 0.2),\n\t\t\t\tCellPosition(x, z) + Vector3.new(0, 0.15, 0),\n\t\t\t\tColor3.fromRGB(110, 80, 50)\n\t\t\t)\n\t\tend\n\tend\nend\n\nlocal cost, cameFrom, openList = { [CellKey(1, 1)] = 0 }, {}, { { 1, 1 } }\n\nwhile #openList > 0 do\n\tlocal bestIndex = 1\n\tfor i = 2, #openList do\n\t\tif\n\t\t\tcost[CellKey(openList[i][1], openList[i][2])]\n\t\t\t< cost[CellKey(openList[bestIndex][1], openList[bestIndex][2])]\n\t\tthen\n\t\t\tbestIndex = i\n\t\tend\n\tend\n\tlocal cell = table.remove(openList, bestIndex)\n\tif cell[1] == _width and cell[2] == _height then break end\n\tfor _, neighbour in Neighbours(cell[1], cell[2]) do\n\t\tlocal neighbourKey = CellKey(neighbour[1], neighbour[2])\n\t\tlocal newCost = cost[CellKey(cell[1], cell[2])] + (mud[neighbourKey] and 5 or 1)\n\t\tif cost[neighbourKey] == nil or newCost < cost[neighbourKey] then\n\t\t\tcost[neighbourKey] = newCost\n\t\t\tcameFrom[neighbourKey] = cell\n\t\t\ttable.insert(openList, neighbour)\n\t\tend\n\tend\nend\n\nlocal path, cell = {}, { _width, _height }\n\nwhile cell do\n\ttable.insert(path, 1, cell)\n\tcell = cameFrom[CellKey(cell[1], cell[2])]\nend\n\nShowPath(path)\nprint(\"total cost\", cost[CellKey(_width, _height)])","runtime":""},
"pf-astar":{"k":"S","what":"A* through a maze: the priority is cost so far plus a Manhattan estimate to the goal, so it explores far fewer cells than Dijkstra.","services":[],"variables":"local _width = 18\nlocal _height = 14\nlocal _cell = 3","functions":"local function CellKey(x, z)\n\treturn x * 1000 + z\nend\n\nlocal function CellPosition(x, z)\n\treturn ORIGIN + Vector3.new((x - _width / 2) * _cell, 0, (z - _height / 2) * _cell)\nend\n\nlocal function ShowPath(path, color)\n\tfor _, cell in path do\n\t\tMakePart(\n\t\t\tVector3.new(1, 0.4, 1),\n\t\t\tCellPosition(cell[1], cell[2]) + Vector3.new(0, 0.4, 0),\n\t\t\tcolor or Color3.fromRGB(226, 133, 26),\n\t\t\t{ CanCollide = false }\n\t\t)\n\tend\nend\n\nlocal function Estimate(x, z)\n\treturn math.abs(x - _width) + math.abs(z - _height)\nend","setup":"local walls = {}\nlocal random = Random.new(7)\n\nfor x = 1, _width do\n\tfor z = 1, _height do\n\t\tMakePart(\n\t\t\tVector3.new(_cell - 0.2, 0.2, _cell - 0.2),\n\t\t\tCellPosition(x, z) + Vector3.new(0, 0.1, 0),\n\t\t\tColor3.fromRGB(200, 200, 205)\n\t\t)\n\t\tif\n\t\t\trandom:NextNumber() < 0.22\n\t\t\tand not (x <= 2 and z <= 2)\n\t\t\tand not (x >= _width - 1 and z >= _height - 1)\n\t\tthen\n\t\t\twalls[CellKey(x, z)] = true\n\t\t\tMakePart(\n\t\t\t\tVector3.new(_cell, 3, _cell),\n\t\t\t\tCellPosition(x, z) + Vector3.new(0, 1.5, 0),\n\t\t\t\tColor3.fromRGB(50, 50, 60)\n\t\t\t)\n\t\tend\n\tend\nend\n\nlocal function IsOpen(x, z)\n\treturn x >= 1 and x <= _width and z >= 1 and z <= _height and not walls[CellKey(x, z)]\nend\n\nlocal function Neighbours(x, z)\n\tlocal list = {}\n\tfor _, direction in { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } } do\n\t\tif IsOpen(x + direction[1], z + direction[2]) then\n\t\t\ttable.insert(list, { x + direction[1], z + direction[2] })\n\t\tend\n\tend\n\treturn list\nend\n\nlocal cost, cameFrom, openList, explored = { [CellKey(1, 1)] = 0 }, {}, { { 1, 1 } }, 0\n\nwhile #openList > 0 do\n\tlocal bestIndex = 1\n\tfor i = 2, #openList do\n\t\tlocal candidate, best = openList[i], openList[bestIndex]\n\t\tif\n\t\t\tcost[CellKey(candidate[1], candidate[2])] + Estimate(candidate[1], candidate[2])\n\t\t\t< cost[CellKey(best[1], best[2])] + Estimate(best[1], best[2])\n\t\tthen\n\t\t\tbestIndex = i\n\t\tend\n\tend\n\tlocal cell = table.remove(openList, bestIndex)\n\texplored += 1\n\tMakePart(\n\t\tVector3.new(_cell - 0.8, 0.3, _cell - 0.8),\n\t\tCellPosition(cell[1], cell[2]) + Vector3.new(0, 0.25, 0),\n\t\tColor3.fromRGB(18, 147, 154),\n\t\t{ CanCollide = false }\n\t)\n\tif cell[1] == _width and cell[2] == _height then break end\n\tfor _, neighbour in Neighbours(cell[1], cell[2]) do\n\t\tlocal neighbourKey = CellKey(neighbour[1], neighbour[2])\n\t\tlocal newCost = cost[CellKey(cell[1], cell[2])] + 1\n\t\tif cost[neighbourKey] == nil or newCost < cost[neighbourKey] then\n\t\t\tcost[neighbourKey] = newCost\n\t\t\tcameFrom[neighbourKey] = cell\n\t\t\ttable.insert(openList, neighbour)\n\t\tend\n\tend\n\ttask.wait(0.02)\nend\n\nlocal path, cell = {}, cameFrom[CellKey(_width, _height)] and { _width, _height } or nil\n\nwhile cell do\n\ttable.insert(path, 1, cell)\n\tcell = cameFrom[CellKey(cell[1], cell[2])]\nend\n\nShowPath(path)\nprint(\"explored\", explored, \"cells\")","runtime":""},
"pf-heuristics":{"k":"S","what":"Runs A* twice on the same maze with 8-way moves: with the octile heuristic (exact) and with none (Dijkstra), and prints how many cells each explored.","services":[],"variables":"local _width = 18\nlocal _height = 14\nlocal _cell = 3\nlocal _sqrt2 = math.sqrt(2)","functions":"local function CellKey(x, z)\n\treturn x * 1000 + z\nend\n\nlocal function CellPosition(x, z)\n\treturn ORIGIN + Vector3.new((x - _width / 2) * _cell, 0, (z - _height / 2) * _cell)\nend\n\nlocal function ShowPath(path, color)\n\tfor _, cell in path do\n\t\tMakePart(\n\t\t\tVector3.new(1, 0.4, 1),\n\t\t\tCellPosition(cell[1], cell[2]) + Vector3.new(0, 0.4, 0),\n\t\t\tcolor or Color3.fromRGB(226, 133, 26),\n\t\t\t{ CanCollide = false }\n\t\t)\n\tend\nend","setup":"local walls = {}\nlocal random = Random.new(7)\n\nfor x = 1, _width do\n\tfor z = 1, _height do\n\t\tMakePart(\n\t\t\tVector3.new(_cell - 0.2, 0.2, _cell - 0.2),\n\t\t\tCellPosition(x, z) + Vector3.new(0, 0.1, 0),\n\t\t\tColor3.fromRGB(200, 200, 205)\n\t\t)\n\t\tif\n\t\t\trandom:NextNumber() < 0.22\n\t\t\tand not (x <= 2 and z <= 2)\n\t\t\tand not (x >= _width - 1 and z >= _height - 1)\n\t\tthen\n\t\t\twalls[CellKey(x, z)] = true\n\t\t\tMakePart(\n\t\t\t\tVector3.new(_cell, 3, _cell),\n\t\t\t\tCellPosition(x, z) + Vector3.new(0, 1.5, 0),\n\t\t\t\tColor3.fromRGB(50, 50, 60)\n\t\t\t)\n\t\tend\n\tend\nend\n\nlocal function IsOpen(x, z)\n\treturn x >= 1 and x <= _width and z >= 1 and z <= _height and not walls[CellKey(x, z)]\nend\n\nlocal function Neighbours(x, z)\n\tlocal list = {}\n\tfor _, direction in { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } } do\n\t\tif IsOpen(x + direction[1], z + direction[2]) then\n\t\t\ttable.insert(list, { x + direction[1], z + direction[2] })\n\t\tend\n\tend\n\treturn list\nend\n\nlocal function Run(useHeuristic)\n\tlocal function Estimate(x, z)\n\t\tif not useHeuristic then return 0 end\n\t\tlocal offsetX, offsetZ = math.abs(x - _width), math.abs(z - _height)\n\t\treturn offsetX + offsetZ + (_sqrt2 - 2) * math.min(offsetX, offsetZ)\n\tend\n\tlocal cost, openList, closed, explored = { [CellKey(1, 1)] = 0 }, { { 1, 1 } }, {}, 0\n\twhile #openList > 0 do\n\t\tlocal bestIndex = 1\n\t\tfor i = 2, #openList do\n\t\t\tlocal candidate, best = openList[i], openList[bestIndex]\n\t\t\tif\n\t\t\t\tcost[CellKey(candidate[1], candidate[2])] + Estimate(candidate[1], candidate[2])\n\t\t\t\t< cost[CellKey(best[1], best[2])] + Estimate(best[1], best[2])\n\t\t\tthen\n\t\t\t\tbestIndex = i\n\t\t\tend\n\t\tend\n\t\tlocal cell = table.remove(openList, bestIndex)\n\t\tif not closed[CellKey(cell[1], cell[2])] then\n\t\t\tclosed[CellKey(cell[1], cell[2])] = true\n\t\t\texplored += 1\n\t\t\tif cell[1] == _width and cell[2] == _height then\n\t\t\t\treturn explored, cost[CellKey(_width, _height)]\n\t\t\tend\n\t\t\tfor offsetX = -1, 1 do\n\t\t\t\tfor offsetZ = -1, 1 do\n\t\t\t\t\tlocal nextX, nextZ = cell[1] + offsetX, cell[2] + offsetZ\n\t\t\t\t\tif\n\t\t\t\t\t\t(offsetX ~= 0 or offsetZ ~= 0)\n\t\t\t\t\t\tand IsOpen(nextX, nextZ)\n\t\t\t\t\t\tand (\n\t\t\t\t\t\t\toffsetX == 0\n\t\t\t\t\t\t\tor offsetZ == 0\n\t\t\t\t\t\t\tor (IsOpen(nextX, cell[2]) and IsOpen(cell[1], nextZ))\n\t\t\t\t\t\t)\n\t\t\t\t\tthen\n\t\t\t\t\t\tlocal neighbourKey = CellKey(nextX, nextZ)\n\t\t\t\t\t\tlocal newCost = cost[CellKey(cell[1], cell[2])]\n\t\t\t\t\t\t\t+ ((offsetX ~= 0 and offsetZ ~= 0) and _sqrt2 or 1)\n\t\t\t\t\t\tif cost[neighbourKey] == nil or newCost < cost[neighbourKey] then\n\t\t\t\t\t\t\tcost[neighbourKey] = newCost\n\t\t\t\t\t\t\ttable.insert(openList, { nextX, nextZ })\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\treturn explored, nil\nend\n\nlocal exploredOctile, lengthOctile = Run(true)\nlocal exploredDijkstra, lengthDijkstra = Run(false)\nprint(string.format(\"A* with octile: explored %d cells, length %.2f\", exploredOctile, lengthOctile or -1))\nprint(string.format(\"Dijkstra:       explored %d cells, length %.2f\", exploredDijkstra, lengthDijkstra or -1))","runtime":""},
"pf-flow":{"k":"S","what":"A flow field: one BFS from the goal gives every cell a distance; 30 balls just step to their lowest neighbour each tick and all reach the goal.","services":[],"variables":"local _width = 18\nlocal _height = 14\nlocal _cell = 3","functions":"local function CellKey(x, z)\n\treturn x * 1000 + z\nend\n\nlocal function CellPosition(x, z)\n\treturn ORIGIN + Vector3.new((x - _width / 2) * _cell, 0, (z - _height / 2) * _cell)\nend\n\nlocal function ShowPath(path, color)\n\tfor _, cell in path do\n\t\tMakePart(\n\t\t\tVector3.new(1, 0.4, 1),\n\t\t\tCellPosition(cell[1], cell[2]) + Vector3.new(0, 0.4, 0),\n\t\t\tcolor or Color3.fromRGB(226, 133, 26),\n\t\t\t{ CanCollide = false }\n\t\t)\n\tend\nend","setup":"local walls = {}\nlocal random = Random.new(7)\n\nfor x = 1, _width do\n\tfor z = 1, _height do\n\t\tMakePart(\n\t\t\tVector3.new(_cell - 0.2, 0.2, _cell - 0.2),\n\t\t\tCellPosition(x, z) + Vector3.new(0, 0.1, 0),\n\t\t\tColor3.fromRGB(200, 200, 205)\n\t\t)\n\t\tif\n\t\t\trandom:NextNumber() < 0.22\n\t\t\tand not (x <= 2 and z <= 2)\n\t\t\tand not (x >= _width - 1 and z >= _height - 1)\n\t\tthen\n\t\t\twalls[CellKey(x, z)] = true\n\t\t\tMakePart(\n\t\t\t\tVector3.new(_cell, 3, _cell),\n\t\t\t\tCellPosition(x, z) + Vector3.new(0, 1.5, 0),\n\t\t\t\tColor3.fromRGB(50, 50, 60)\n\t\t\t)\n\t\tend\n\tend\nend\n\nlocal function IsOpen(x, z)\n\treturn x >= 1 and x <= _width and z >= 1 and z <= _height and not walls[CellKey(x, z)]\nend\n\nlocal function Neighbours(x, z)\n\tlocal list = {}\n\tfor _, direction in { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } } do\n\t\tif IsOpen(x + direction[1], z + direction[2]) then\n\t\t\ttable.insert(list, { x + direction[1], z + direction[2] })\n\t\tend\n\tend\n\treturn list\nend\n\nlocal goal = { _width, _height }\nlocal distance = { [CellKey(_width, _height)] = 0 }\nlocal queue, head = { goal }, 1\n\nwhile head <= #queue do\n\tlocal cell = queue[head]\n\thead += 1\n\tfor _, neighbour in Neighbours(cell[1], cell[2]) do\n\t\tif distance[CellKey(neighbour[1], neighbour[2])] == nil then\n\t\t\tdistance[CellKey(neighbour[1], neighbour[2])] = distance[CellKey(cell[1], cell[2])] + 1\n\t\t\ttable.insert(queue, neighbour)\n\t\tend\n\tend\nend\n\nMakePart(\n\tVector3.new(2, 2, 2),\n\tCellPosition(_width, _height) + Vector3.new(0, 1, 0),\n\tColor3.fromRGB(230, 60, 60),\n\t{ Material = Enum.Material.Neon }\n)\n\nlocal units = {}\nlocal random = Random.new()\n\nwhile #units < 30 do\n\tlocal x, z = random:NextInteger(1, _width), random:NextInteger(1, _height)\n\tif distance[CellKey(x, z)] then\n\t\ttable.insert(units, {\n\t\t\tX = x,\n\t\t\tZ = z,\n\t\t\tPart = MakePart(\n\t\t\t\tVector3.new(1, 1, 1),\n\t\t\t\tCellPosition(x, z) + Vector3.new(0, 1, 0),\n\t\t\t\tColor3.fromRGB(226, 133, 26),\n\t\t\t\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n\t\t\t),\n\t\t})\n\tend\nend","runtime":"while true do\n\tfor _, unit in units do\n\t\tlocal best, bestDistance = nil, distance[CellKey(unit.X, unit.Z)]\n\t\tfor _, neighbour in Neighbours(unit.X, unit.Z) do\n\t\t\tlocal neighbourDistance = distance[CellKey(neighbour[1], neighbour[2])]\n\t\t\tif neighbourDistance and neighbourDistance < bestDistance then\n\t\t\t\tbest, bestDistance = neighbour, neighbourDistance\n\t\t\tend\n\t\tend\n\t\tif best then\n\t\t\tunit.X, unit.Z = best[1], best[2]\n\t\tend\n\t\ttweenService\n\t\t\t:Create(\n\t\t\t\tunit.Part,\n\t\t\t\tTweenInfo.new(0.25, Enum.EasingStyle.Linear),\n\t\t\t\t{ Position = CellPosition(unit.X, unit.Z) + Vector3.new(0, 1, 0) }\n\t\t\t)\n\t\t\t:Play()\n\tend\n\ttask.wait(0.25)\nend"},
"pf-smooth":{"k":"S","what":"Finds a grid path with BFS, then string-pulls it: from each kept point, skip to the furthest point with clear line of sight. Grey = raw, orange = smoothed.","services":[],"variables":"local _width = 18\nlocal _height = 14\nlocal _cell = 3","functions":"local function CellKey(x, z)\n\treturn x * 1000 + z\nend\n\nlocal function CellPosition(x, z)\n\treturn ORIGIN + Vector3.new((x - _width / 2) * _cell, 0, (z - _height / 2) * _cell)\nend\n\nlocal function ShowPath(path, color)\n\tfor _, cell in path do\n\t\tMakePart(\n\t\t\tVector3.new(1, 0.4, 1),\n\t\t\tCellPosition(cell[1], cell[2]) + Vector3.new(0, 0.4, 0),\n\t\t\tcolor or Color3.fromRGB(226, 133, 26),\n\t\t\t{ CanCollide = false }\n\t\t)\n\tend\nend","setup":"local walls = {}\nlocal random = Random.new(7)\n\nfor x = 1, _width do\n\tfor z = 1, _height do\n\t\tMakePart(\n\t\t\tVector3.new(_cell - 0.2, 0.2, _cell - 0.2),\n\t\t\tCellPosition(x, z) + Vector3.new(0, 0.1, 0),\n\t\t\tColor3.fromRGB(200, 200, 205)\n\t\t)\n\t\tif\n\t\t\trandom:NextNumber() < 0.22\n\t\t\tand not (x <= 2 and z <= 2)\n\t\t\tand not (x >= _width - 1 and z >= _height - 1)\n\t\tthen\n\t\t\twalls[CellKey(x, z)] = true\n\t\t\tMakePart(\n\t\t\t\tVector3.new(_cell, 3, _cell),\n\t\t\t\tCellPosition(x, z) + Vector3.new(0, 1.5, 0),\n\t\t\t\tColor3.fromRGB(50, 50, 60)\n\t\t\t)\n\t\tend\n\tend\nend\n\nlocal function IsOpen(x, z)\n\treturn x >= 1 and x <= _width and z >= 1 and z <= _height and not walls[CellKey(x, z)]\nend\n\nlocal function Neighbours(x, z)\n\tlocal list = {}\n\tfor _, direction in { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } } do\n\t\tif IsOpen(x + direction[1], z + direction[2]) then\n\t\t\ttable.insert(list, { x + direction[1], z + direction[2] })\n\t\tend\n\tend\n\treturn list\nend\n\nlocal cameFrom = { [CellKey(1, 1)] = false }\nlocal queue, head = { { 1, 1 } }, 1\n\nwhile head <= #queue do\n\tlocal cell = queue[head]\n\thead += 1\n\tfor _, neighbour in Neighbours(cell[1], cell[2]) do\n\t\tif cameFrom[CellKey(neighbour[1], neighbour[2])] == nil then\n\t\t\tcameFrom[CellKey(neighbour[1], neighbour[2])] = cell\n\t\t\ttable.insert(queue, neighbour)\n\t\tend\n\tend\nend\n\nlocal path, cell = {}, cameFrom[CellKey(_width, _height)] ~= nil and { _width, _height } or nil\n\nwhile cell do\n\ttable.insert(path, 1, cell)\n\tcell = cameFrom[CellKey(cell[1], cell[2])]\nend\n\nShowPath(path, Color3.fromRGB(140, 140, 150))\n\nlocal function LineOfSight(fromCell, toCell)\n\tlocal startX, startZ, endX, endZ = fromCell[1], fromCell[2], toCell[1], toCell[2]\n\tlocal deltaX, deltaZ = math.abs(endX - startX), -math.abs(endZ - startZ)\n\tlocal stepX, stepZ = startX < endX and 1 or -1, startZ < endZ and 1 or -1\n\tlocal errorTerm = deltaX + deltaZ\n\twhile true do\n\t\tif not IsOpen(startX, startZ) then return false end\n\t\tif startX == endX and startZ == endZ then return true end\n\t\tlocal doubledError = 2 * errorTerm\n\t\tif doubledError >= deltaZ then\n\t\t\terrorTerm += deltaZ\n\t\t\tstartX += stepX\n\t\tend\n\t\tif doubledError <= deltaX then\n\t\t\terrorTerm += deltaX\n\t\t\tstartZ += stepZ\n\t\tend\n\tend\nend\n\nlocal kept, i = { path[1] }, 1\n\nwhile path[i] and i < #path do\n\tlocal j = #path\n\twhile j > i + 1 and not LineOfSight(path[i], path[j]) do\n\t\tj -= 1\n\tend\n\ttable.insert(kept, path[j])\n\ti = j\nend\n\nfor index = 1, #kept - 1 do\n\tDrawLine(\n\t\tMakeLinePart(),\n\t\tCellPosition(kept[index][1], kept[index][2]) + Vector3.new(0, 1, 0),\n\t\tCellPosition(kept[index + 1][1], kept[index + 1][2]) + Vector3.new(0, 1, 0)\n\t)\nend\n\nprint(#path, \"waypoints ->\", #kept)","runtime":""},
"pf-waypoints":{"k":"S","what":"A small graph of waypoint pads joined by edges. Dijkstra finds the shortest route from pad 1 to pad 8 and a ball walks it.","services":[],"variables":"","functions":"","setup":"local NODES = {\n\tVector3.new(-14, 0, -8),\n\tVector3.new(-6, 0, -12),\n\tVector3.new(2, 0, -8),\n\tVector3.new(12, 0, -10),\n\tVector3.new(-12, 0, 4),\n\tVector3.new(-2, 0, 2),\n\tVector3.new(6, 0, 6),\n\tVector3.new(14, 0, 8),\n}\n\nlocal EDGES = {\n\t{ 1, 2 },\n\t{ 2, 3 },\n\t{ 3, 4 },\n\t{ 1, 5 },\n\t{ 2, 6 },\n\t{ 3, 6 },\n\t{ 3, 7 },\n\t{ 4, 8 },\n\t{ 5, 6 },\n\t{\n\t\t6,\n\t\t7,\n\t},\n\t{\n\t\t7,\n\t\t8,\n\t},\n}\n\nlocal graph = {}\n\nfor i, point in NODES do\n\tgraph[i] = {}\n\tMakeLabel(MakePart(Vector3.new(2, 0.4, 2), ORIGIN + point, Color3.fromRGB(18, 147, 154)), tostring(i))\nend\n\nfor _, edge in EDGES do\n\tlocal length = (NODES[edge[1]] - NODES[edge[2]]).Magnitude\n\ttable.insert(graph[edge[1]], { edge[2], length })\n\ttable.insert(graph[edge[2]], { edge[1], length })\n\tDrawLine(\n\t\tMakeLinePart(Color3.fromRGB(120, 120, 130)),\n\t\tORIGIN + NODES[edge[1]] + Vector3.new(0, 0.3, 0),\n\t\tORIGIN + NODES[edge[2]] + Vector3.new(0, 0.3, 0)\n\t)\nend\n\nlocal distance, previousNode, visited = {}, {}, {}\n\nfor i = 1, #NODES do\n\tdistance[i] = math.huge\nend\n\ndistance[1] = 0\n\nfor _ = 1, #NODES do\n\tlocal current\n\tfor i = 1, #NODES do\n\t\tif not visited[i] and (not current or distance[i] < distance[current]) then current = i end\n\tend\n\tvisited[current] = true\n\tfor _, edge in graph[current] do\n\t\tlocal neighbour, weight = edge[1], edge[2]\n\t\tif distance[current] + weight < distance[neighbour] then\n\t\t\tdistance[neighbour] = distance[current] + weight\n\t\t\tpreviousNode[neighbour] = current\n\t\tend\n\tend\nend\n\nlocal route, node = {}, 8\n\nwhile node do\n\ttable.insert(route, 1, node)\n\tnode = previousNode[node]\nend\n\nprint(\"route:\", table.concat(route, \" -> \"), string.format(\"(%.1f studs)\", distance[8]))\n\nlocal walker = MakePart(\n\tVector3.new(1.5, 1.5, 1.5),\n\tORIGIN + NODES[1] + Vector3.new(0, 1, 0),\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball }\n)","runtime":"while true do\n\tfor _, i in route do\n\t\tlocal tween = tweenService:Create(\n\t\t\twalker,\n\t\t\tTweenInfo.new(0.8, Enum.EasingStyle.Linear),\n\t\t\t{ Position = ORIGIN + NODES[i] + Vector3.new(0, 1, 0) }\n\t\t)\n\t\ttween:Play()\n\t\ttween.Completed:Wait()\n\tend\n\twalker.Position = ORIGIN + NODES[1] + Vector3.new(0, 1, 0)\nend"},
"pf-follow":{"k":"S","what":"A ball follows a list of waypoints, moving on to the next one when it gets within an arrive radius instead of touching it exactly.","services":[],"variables":"local _radius = 1.5\nlocal _speed = 10","functions":"","setup":"local WAYPOINTS = {\n\tVector3.new(-12, 1, -8),\n\tVector3.new(-12, 1, 6),\n\tVector3.new(-2, 1, 6),\n\tVector3.new(-2, 1, -4),\n\tVector3.new(8, 1, -4),\n\tVector3.new(8, 1, 8),\n\tVector3.new(14, 1, 8),\n}\n\nfor _, waypoint in WAYPOINTS do\n\tMakePart(\n\t\tVector3.new(_radius * 2, 0.2, _radius * 2),\n\t\tORIGIN + waypoint - Vector3.new(0, 0.9, 0),\n\t\tColor3.fromRGB(18, 147, 154),\n\t\t{\n\t\t\tShape = Enum.PartType.Cylinder,\n\t\t\tOrientation = Vector3.new(0, 0, 90),\n\t\t\tTransparency = 0.5,\n\t\t\tCanCollide = false,\n\t\t}\n\t)\nend\n\nlocal walker = MakePart(\n\tVector3.new(1.4, 1.4, 1.4),\n\tORIGIN + WAYPOINTS[1],\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n)\n\nlocal index = 2","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tlocal goal = ORIGIN + WAYPOINTS[index]\n\tlocal offset = goal - walker.Position\n\tif offset.Magnitude < _radius then\n\t\tindex += 1\n\t\tif index > #WAYPOINTS then\n\t\t\tindex = 2\n\t\t\twalker.Position = ORIGIN + WAYPOINTS[1]\n\t\tend\n\t\treturn\n\tend\n\twalker.Position += offset.Unit * math.min(_speed * deltaTime, offset.Magnitude)\nend)"},
"mx-columns":{"k":"S","what":"Prints a turning part's 12 CFrame components and shows that the rotation columns are its Right, Up and Back vectors.","services":[],"variables":"","functions":"","setup":"local part = MakePart(Vector3.new(2, 1, 4), ORIGIN + Vector3.new(0, 4, 0), Color3.fromRGB(226, 133, 26))\nlocal label = MakeLabel(part)","runtime":"runService.Heartbeat:Connect(function()\n\tpart.CFrame = CFrame.new(part.Position)\n\t\t* CFrame.fromEulerAnglesYXZ(math.sin(os.clock()) * 0.4, os.clock() * 0.5, 0)\n\tlocal x, y, z, R00, R01, R02, R10, R11, R12, R20, R21, R22 = part.CFrame:GetComponents()\n\tlabel.Text =\n\t\tstring.format(\"Right (%.2f, %.2f, %.2f)  Look (%.2f, %.2f, %.2f)\", R00, R10, R20, -R02, -R12, -R22)\nend)"},
"mx-mulvec":{"k":"S","what":"A marker sits at a fixed local offset from a spinning part, worked out as Position + Right·x + Up·y − Look·z (the same as cf * v).","services":[],"variables":"","functions":"","setup":"local part = MakePart(Vector3.new(2, 1, 4), ORIGIN + Vector3.new(0, 3, 0), Color3.fromRGB(163, 162, 165))\n\nlocal marker = MakePart(\n\tVector3.new(1, 1, 1),\n\tORIGIN,\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n)\n\nlocal localOffset = Vector3.new(3, 2, -2)","runtime":"runService.Heartbeat:Connect(function()\n\tpart.CFrame = CFrame.new(part.Position) * CFrame.Angles(0, os.clock(), 0)\n\tlocal frame = part.CFrame\n\tmarker.Position = frame.Position\n\t\t+ frame.RightVector * localOffset.X\n\t\t+ frame.UpVector * localOffset.Y\n\t\t- frame.LookVector * localOffset.Z -- = cf * v\nend)"},
"mx-fk":{"k":"S","what":"A three-joint robot arm animated with forward kinematics: each joint is parent × rotation × offset along the bone.","services":[],"variables":"","functions":"","setup":"local LENGTHS = { 4, 3.5, 2.5 }\nlocal BASE = CFrame.new(ORIGIN + Vector3.new(0, 1, 0))\nlocal bones = {}\n\nfor i, boneLength in LENGTHS do\n\tbones[i] = MakePart(\n\t\tVector3.new(0.9, boneLength, 0.9),\n\t\tORIGIN,\n\t\tColor3.fromHSV(i / 4, 0.6, 0.9),\n\t\t{ CanCollide = false }\n\t)\nend","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tlocal angles = { math.sin(now * 0.8) * 0.8, math.sin(now * 1.1) * 1.2 - 0.6, math.sin(now * 1.7) * 0.9 }\n\tlocal frame = BASE * CFrame.Angles(0, now * 0.3, 0)\n\tfor i, boneLength in LENGTHS do\n\t\tframe = frame * CFrame.Angles(0, 0, angles[i])\n\t\tbones[i].CFrame = frame * CFrame.new(0, boneLength / 2, 0)\n\t\tframe = frame * CFrame.new(0, boneLength, 0)\n\tend\nend)"},
"mx-inverse":{"k":"S","what":"Shows that cf:Inverse() undoes cf: a point turned into local space and back lands exactly where it started.","services":[],"variables":"","functions":"","setup":"local part = MakePart(Vector3.new(2, 1, 4), ORIGIN + Vector3.new(0, 3, 0), Color3.fromRGB(226, 133, 26))\npart.CFrame = CFrame.new(part.Position) * CFrame.fromEulerAnglesYXZ(0.3, 0.8, 0.1)\nlocal world = ORIGIN + Vector3.new(5, 4, -3)\nlocal localPoint = part.CFrame:Inverse() * world\nlocal back = part.CFrame * localPoint\nprint(\"local:\", localPoint, \" back to world:\", back, \" error:\", (back - world).Magnitude)\nprint(\"cf:Inverse() * cf is identity:\", (part.CFrame:Inverse() * part.CFrame).Position.Magnitude < 1e-6)\nMakeLabel(part, string.format(\"local point (%.1f, %.1f, %.1f)\", localPoint.X, localPoint.Y, localPoint.Z))","runtime":""},
"mx-orthonormal":{"k":"S","what":"Spins a part by multiplying its CFrame onto itself every frame (which slowly drifts), and calls :Orthonormalize() every 100 frames to keep it square.","services":[],"variables":"","functions":"","setup":"local part = MakePart(Vector3.new(2, 1, 4), ORIGIN + Vector3.new(0, 3, 0), Color3.fromRGB(226, 133, 26))\nlocal label = MakeLabel(part)\nlocal frames = 0","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tpart.CFrame = part.CFrame * CFrame.Angles(deltaTime * 0.7, deltaTime * 1.1, deltaTime * 0.3)\n\tframes += 1\n\tif frames % 100 == 0 then part.CFrame = part.CFrame:Orthonormalize() end\n\tlocal frame = part.CFrame\n\tlocal skew = math.abs(frame.RightVector:Dot(frame.UpVector))\n\t\t+ math.abs(frame.UpVector:Dot(frame.LookVector))\n\tlabel.Text = string.format(\"frames %d  skew %.1e\", frames, skew)\nend)"},
"mx-basis":{"k":"L","what":"A marker moves in front of you in camera-relative directions as you hold WASD: the input is turned into world space with the camera's flattened axes.","services":["UserInputService"],"variables":"","functions":"","setup":"local marker = MakePart(\n\tVector3.new(1.5, 1.5, 1.5),\n\tORIGIN,\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false, CanQuery = false }\n)\n\nlocal offset = Vector3.zero","runtime":"runService.RenderStepped:Connect(function(deltaTime)\n\tlocal root = GetMyRootPart()\n\tif not root then return end\n\tlocal input = Vector2.new(\n\t\t(userInputService:IsKeyDown(Enum.KeyCode.D) and 1 or 0)\n\t\t\t- (userInputService:IsKeyDown(Enum.KeyCode.A) and 1 or 0),\n\t\t(userInputService:IsKeyDown(Enum.KeyCode.W) and 1 or 0)\n\t\t\t- (userInputService:IsKeyDown(Enum.KeyCode.S) and 1 or 0)\n\t)\n\tlocal look = camera.CFrame.LookVector\n\tlocal forward = Vector3.new(look.X, 0, look.Z).Unit\n\tlocal right = Vector3.new(-forward.Z, 0, forward.X)\n\tlocal move = right * input.X + forward * input.Y\n\toffset = offset:Lerp(move * 6, 1 - math.exp(-6 * deltaTime))\n\tmarker.Position = root.Position + Vector3.new(0, 3, 0) + offset\nend)"},
"mx-scale":{"k":"S","what":"A small house model grows and shrinks around its base: each part's size and its offset from the pivot are scaled by the same factor.","services":[],"variables":"","functions":"","setup":"local pivot = ORIGIN\n\nlocal layout = {\n\t{ Vector3.new(0, 2, 0), Vector3.new(6, 4, 6), Color3.fromRGB(220, 200, 170) },\n\t{ Vector3.new(0, 5, 0), Vector3.new(7, 2, 7), Color3.fromRGB(170, 60, 50) },\n\t{ Vector3.new(0, 1.2, -3.05), Vector3.new(1.5, 2.4, 0.2), Color3.fromRGB(100, 70, 40) },\n}\n\nlocal parts = {}\n\nfor i, entry in layout do\n\tparts[i] = MakePart(entry[2], pivot + entry[1], entry[3])\nend","runtime":"runService.Heartbeat:Connect(function()\n\tlocal scale = 1 + 0.5 * math.sin(os.clock())\n\tfor i, entry in layout do\n\t\tparts[i].Size = entry[2] * scale\n\t\tparts[i].Position = pivot + entry[1] * scale -- offset from the pivot grows too\n\tend\nend)"},
"mx-mirror":{"k":"S","what":"A spinning arrow and its mirror twin across a glass plane. Positions and axes are reflected, then the frame is rebuilt with CFrame.lookAt.","services":[],"variables":"","functions":"local function Reflect(vector)\n\treturn Vector3.new(-vector.X, vector.Y, vector.Z)\nend","setup":"local MIRROR_X = ORIGIN.X\n\nMakePart(\n\tVector3.new(0.2, 10, 16),\n\tORIGIN + Vector3.new(0, 5, 0),\n\tColor3.fromRGB(150, 200, 255),\n\t{ Transparency = 0.7, CanCollide = false }\n)\n\nlocal original = MakePart(Vector3.new(1, 1, 4), ORIGIN, Color3.fromRGB(226, 133, 26))\nlocal twin = MakePart(Vector3.new(1, 1, 4), ORIGIN, Color3.fromRGB(226, 133, 26), { Transparency = 0.4 })","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\toriginal.CFrame = CFrame.new(ORIGIN + Vector3.new(5 + math.sin(now) * 2, 4, math.cos(now) * 4))\n\t\t* CFrame.fromEulerAnglesYXZ(math.sin(now) * 0.5, now, 0)\n\tlocal originalPosition = original.Position\n\tlocal mirroredPosition =\n\t\tVector3.new(2 * MIRROR_X - originalPosition.X, originalPosition.Y, originalPosition.Z)\n\ttwin.CFrame = CFrame.lookAt(\n\t\tmirroredPosition,\n\t\tmirroredPosition + Reflect(original.CFrame.LookVector),\n\t\tReflect(original.CFrame.UpVector)\n\t)\nend)"},
"cl-derivative":{"k":"S","what":"A ball moves up and down; its speed is measured with a numeric derivative of the position function and shown as an arrow.","services":[],"variables":"","functions":"local function Height(now)\n\treturn 6 + 3 * math.sin(now * 1.5)\nend","setup":"local ball = MakePart(\n\tVector3.new(1.5, 1.5, 1.5),\n\tORIGIN,\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n)\n\nlocal arrow = MakeLinePart(Color3.fromRGB(18, 147, 154))\nlocal label = MakeLabel(ball)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tlocal step = 0.001\n\tlocal velocity = (Height(now + step) - Height(now - step)) / (2 * step) -- slope of the height curve\n\tball.Position = ORIGIN + Vector3.new(0, Height(now), 0)\n\tDrawLine(arrow, ball.Position, ball.Position + Vector3.new(0, velocity * 0.5, 0))\n\tlabel.Text = string.format(\"speed %.2f\", velocity)\nend)"},
"cl-velocity":{"k":"S","what":"A label over each player shows their speed measured from position samples over the last 8 frames (Δposition ÷ Δtime).","services":[],"variables":"","functions":"","setup":"local history, labels = {}, {}","runtime":"runService.Heartbeat:Connect(function()\n\tfor _, player in players:GetPlayers() do\n\t\tlocal root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\t\tif root then\n\t\t\tlocal playerHistory = history[player] or {}\n\t\t\thistory[player] = playerHistory\n\t\t\ttable.insert(playerHistory, { os.clock(), root.Position })\n\t\t\tif #playerHistory > 9 then table.remove(playerHistory, 1) end\n\t\t\tif not labels[player] or not labels[player].Parent or labels[player].Parent.Parent ~= root then\n\t\t\t\tlabels[player] = MakeLabel(root)\n\t\t\tend\n\t\t\tif #playerHistory >= 2 then\n\t\t\t\tlocal oldest, newest = playerHistory[1], playerHistory[#playerHistory]\n\t\t\t\tlocal velocity = (newest[2] - oldest[2]) / (newest[1] - oldest[1])\n\t\t\t\tlabels[player].Text = string.format(\"%.1f studs/s\", velocity.Magnitude)\n\t\t\tend\n\t\tend\n\tend\nend)"},
"cl-integral":{"k":"S","what":"A car accelerates, cruises and brakes. Distance is the running sum of speed × dt (an integral), and the odometer shows it.","services":[],"variables":"","functions":"local function SpeedAt(elapsed)\n\tif elapsed < 3 then\n\t\treturn 4 * elapsed\n\telseif elapsed < 7 then\n\t\treturn 12\n\telse\n\t\treturn math.max(0, 12 - 4 * (elapsed - 7))\n\tend\nend","setup":"local car = MakePart(Vector3.new(4, 2, 2), ORIGIN + Vector3.new(-25, 1, 0), Color3.fromRGB(230, 60, 60))\nlocal label = MakeLabel(car)","runtime":"while true do\n\tlocal elapsed, distance = 0, 0\n\twhile elapsed < 10 do\n\t\tlocal deltaTime = runService.Heartbeat:Wait()\n\t\telapsed += deltaTime\n\t\tdistance += SpeedAt(elapsed) * deltaTime -- add up speed × time\n\t\tcar.Position = ORIGIN + Vector3.new(-25 + distance * 0.6, 1, 0)\n\t\tlabel.Text = string.format(\"speed %.1f   travelled %.1f\", SpeedAt(elapsed), distance)\n\tend\n\ttask.wait(1)\nend"},
"cl-newton":{"k":"S","what":"Solves \"when does a ball thrown up at 18 studs/s reach height 6?\" with Newton's method and prints each guess.","services":[],"variables":"local _gravity = 20","functions":"local function HeightError(guess)\n\treturn 18 * guess - 0.5 * _gravity * guess * guess - 6\nend\n\nlocal function HeightErrorSlope(guess)\n\treturn 18 - _gravity * guess\nend","setup":"local guess = 0.1\n\nfor i = 1, 6 do\n\tguess = guess - HeightError(guess) / HeightErrorSlope(guess)\n\tprint(string.format(\"guess %d: t = %.6f  (f = %.2e)\", i, guess, HeightError(guess)))\nend\n\nlocal ball = MakePart(\n\tVector3.new(1, 1, 1),\n\tORIGIN,\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n)\n\nlocal mark = MakePart(\n\tVector3.new(4, 0.2, 4),\n\tORIGIN + Vector3.new(0, 6, 0),\n\tColor3.fromRGB(18, 147, 154),\n\t{ Transparency = 0.5, CanCollide = false }\n)\n\nMakeLabel(mark, string.format(\"height 6 at t = %.3f s\", guess))","runtime":"while true do\n\tlocal start = os.clock()\n\twhile os.clock() - start < 1.8 do\n\t\tlocal elapsed = os.clock() - start\n\t\tball.Position = ORIGIN\n\t\t\t+ Vector3.new(0, math.max(0, 18 * elapsed - 0.5 * _gravity * elapsed * elapsed), 0)\n\t\trunService.Heartbeat:Wait()\n\tend\nend"},
"cl-bisection":{"k":"S","what":"Uses bisection to find the distance where a falling-off light reaches exactly 25% brightness, and places a marker there.","services":[],"variables":"","functions":"local function Brightness(distance)\n\treturn 1 / (1 + 0.02 * distance * distance)\nend\n\nlocal function BrightnessError(distance)\n\treturn Brightness(distance) - 0.25\nend","setup":"local low, high = 0, 40\n\nfor i = 1, 25 do\n\tlocal middle = (low + high) / 2\n\tif math.sign(BrightnessError(low)) ~= math.sign(BrightnessError(middle)) then\n\t\thigh = middle\n\telse\n\t\tlow = middle\n\tend\nend\n\nlocal distance = (low + high) / 2\nprint(string.format(\"25%% brightness at %.4f studs\", distance))\n\nlocal lamp = MakePart(\n\tVector3.new(1.5, 1.5, 1.5),\n\tORIGIN + Vector3.new(0, 2, 0),\n\tColor3.fromRGB(255, 220, 120),\n\t{ Material = Enum.Material.Neon }\n)\n\nlocal light = Instance.new(\"PointLight\")\nlight.Range = 40\nlight.Parent = lamp\n\nlocal mark =\n\tMakePart(Vector3.new(1, 4, 1), ORIGIN + Vector3.new(distance, 2, 0), Color3.fromRGB(226, 133, 26))\n\nMakeLabel(mark, string.format(\"25%% here (%.2f studs)\", distance))","runtime":""},
"cl-gradient":{"k":"S","what":"Balls roll downhill on noise terrain using gradient descent: measure the slope numerically, step against it, repeat.","services":[],"variables":"local _size = 24\nlocal _cell = 2\nlocal _stepSize = 3","functions":"local function Height(x, z)\n\treturn 4 + 3 * math.noise(x * 0.06 + 0.3, z * 0.06 + 0.7, 3) + 0.01 * ((x - 24) ^ 2 + (z - 24) ^ 2)\nend\n\nlocal function Gradient(x, z)\n\tlocal epsilon = 0.05\n\treturn (Height(x + epsilon, z) - Height(x - epsilon, z)) / (2 * epsilon),\n\t\t(Height(x, z + epsilon) - Height(x, z - epsilon)) / (2 * epsilon)\nend","setup":"for i = 1, _size do\n\tfor j = 1, _size do\n\t\tlocal x, z = i * _cell, j * _cell\n\t\tlocal columnHeight = Height(x, z)\n\t\tMakePart(\n\t\t\tVector3.new(_cell, columnHeight, _cell),\n\t\t\tORIGIN + Vector3.new(x - _size, columnHeight / 2, z - _size),\n\t\t\tColor3.fromRGB(70, 150, 90)\n\t\t\t\t:Lerp(Color3.fromRGB(240, 230, 200), math.clamp((columnHeight - 2) / 8, 0, 1))\n\t\t)\n\tend\n\ttask.wait()\nend\n\nlocal random = Random.new()\n\nfor _ = 1, 5 do\n\ttask.spawn(function()\n\t\tlocal ball = MakePart(\n\t\t\tVector3.new(1.4, 1.4, 1.4),\n\t\t\tORIGIN,\n\t\t\tColor3.fromHSV(random:NextNumber(), 0.7, 1),\n\t\t\t{ Shape = Enum.PartType.Ball, CanCollide = false, Material = Enum.Material.Neon }\n\t\t)\n\t\twhile true do\n\t\t\tlocal x, z = random:NextNumber(_cell, _size * _cell), random:NextNumber(_cell, _size * _cell)\n\t\t\tfor _ = 1, 100 do\n\t\t\t\tlocal slopeX, slopeZ = Gradient(x, z)\n\t\t\t\tx = math.clamp(x - _stepSize * slopeX, _cell, _size * _cell)\n\t\t\t\tz = math.clamp(z - _stepSize * slopeZ, _cell, _size * _cell)\n\t\t\t\tball.Position = ORIGIN + Vector3.new(x - _size, Height(x, z) + 1, z - _size)\n\t\t\t\ttask.wait(0.05)\n\t\t\tend\n\t\tend\n\tend)\nend","runtime":""},
"cl-arclength":{"k":"S","what":"Measures the length of a curved path by adding up straight pieces, printing the estimate for 2, 8, 32 and 128 pieces.","services":[],"variables":"","functions":"local function PointAt(t)\n\treturn ORIGIN + Vector3.new(-12 + 24 * t, 3 + 3 * math.sin(t * math.pi * 3), 0)\nend\n\nlocal function ArcLength(pieces)\n\tlocal total, previous = 0, PointAt(0)\n\tfor i = 1, pieces do\n\t\tlocal point = PointAt(i / pieces)\n\t\ttotal += (point - previous).Magnitude\n\t\tprevious = point\n\tend\n\treturn total\nend","setup":"for _, pieces in { 2, 8, 32, 128 } do\n\tprint(pieces, \"pieces:\", string.format(\"%.3f\", ArcLength(pieces)))\nend\n\nfor i = 0, 128 do\n\tMakePart(\n\t\tVector3.new(0.3, 0.3, 0.3),\n\t\tPointAt(i / 128),\n\t\tColor3.fromRGB(226, 133, 26),\n\t\t{ CanCollide = false }\n\t)\nend\n\nlocal sign = MakePart(Vector3.new(1, 1, 1), ORIGIN + Vector3.new(0, 9, 0), Color3.new(1, 1, 1))\nMakeLabel(sign, string.format(\"length about %.2f studs\", ArcLength(256)))","runtime":""},
"cl-continuity":{"k":"S","what":"Two blocks go through the same waypoints: linear legs (speed jumps at each point) vs a Catmull-Rom spline (smooth speed).","services":[],"variables":"","functions":"local function CatmullRom(p0, p1, p2, p3, alpha)\n\treturn 0.5\n\t\t* (\n\t\t\t(2 * p1)\n\t\t\t+ (p2 - p0) * alpha\n\t\t\t+ (2 * p0 - 5 * p1 + 4 * p2 - p3) * alpha ^ 2\n\t\t\t+ (3 * p1 - p0 - 3 * p2 + p3) * alpha ^ 3\n\t\t)\nend","setup":"local WAYPOINTS =\n\t{ Vector3.new(-14, 2, 0), Vector3.new(-5, 6, -6), Vector3.new(4, 2, 6), Vector3.new(14, 6, 0) }\n\nfor _, point in WAYPOINTS do\n\tMakePart(Vector3.new(0.8, 0.8, 0.8), ORIGIN + point, Color3.fromRGB(194, 65, 142), { CanCollide = false })\nend\n\nlocal linear =\n\tMakePart(Vector3.new(1.5, 1.5, 1.5), ORIGIN, Color3.fromRGB(230, 60, 60), { CanCollide = false })\n\nlocal smooth =\n\tMakePart(Vector3.new(1.5, 1.5, 1.5), ORIGIN, Color3.fromRGB(226, 133, 26), { CanCollide = false })\n\nMakeLabel(linear, \"linear\")\nMakeLabel(smooth, \"spline\")\n\nlocal function Waypoint(i)\n\treturn ORIGIN + WAYPOINTS[math.clamp(i, 1, #WAYPOINTS)]\nend","runtime":"runService.Heartbeat:Connect(function()\n\tlocal progress = (os.clock() * 0.6) % 3\n\tlocal i, alpha = math.floor(progress) + 1, progress % 1\n\tlinear.Position = Waypoint(i):Lerp(Waypoint(i + 1), alpha)\n\tsmooth.Position = CatmullRom(Waypoint(i - 1), Waypoint(i), Waypoint(i + 1), Waypoint(i + 2), alpha)\n\t\t+ Vector3.new(0, 0, 2)\nend)"},
"sp-brute":{"k":"S","what":"Counts how many pair checks \"everyone vs everyone\" needs as the object count grows, and prints the table.","services":[],"variables":"","functions":"","setup":"for _, count in { 10, 50, 100, 400, 1000 } do\n\tprint(string.format(\"%5d objects -> %7d pair checks\", count, count * (count - 1) / 2))\nend\n\nlocal parts = {}\n\nfor i = 1, 20 do\n\tparts[i] = MakePart(\n\t\tVector3.new(1, 1, 1),\n\t\tORIGIN + Vector3.new(math.random(-10, 10), 1, math.random(-10, 10)),\n\t\tColor3.fromRGB(18, 147, 154),\n\t\t{ Shape = Enum.PartType.Ball }\n\t)\nend\n\nlocal checks = 0\n\nfor i = 1, #parts do\n\tfor j = i + 1, #parts do\n\t\tchecks += 1\n\t\tif (parts[i].Position - parts[j].Position).Magnitude < 4 then\n\t\t\tDrawLine(MakeLinePart(Color3.fromRGB(230, 60, 60)), parts[i].Position, parts[j].Position)\n\t\tend\n\tend\nend\n\nprint(\"20 objects took\", checks, \"checks\")","runtime":""},
"sp-hash":{"k":"S","what":"300 dots in a spatial hash. Every frame the dots within 10 studs of you are found by checking only the nearby grid cells, and turn orange.","services":[],"variables":"local _cell = 8\nlocal _radius = 10","functions":"local function CellKey(position)\n\treturn math.floor(position.X / _cell) .. \",\" .. math.floor(position.Z / _cell)\nend","setup":"local random = Random.new()\n\nlocal function Scatter(count, area)\n\tlocal parts = {}\n\tfor i = 1, count do\n\t\tparts[i] = MakePart(\n\t\t\tVector3.new(0.8, 0.8, 0.8),\n\t\t\tORIGIN + Vector3.new(random:NextNumber(-area, area), 1, random:NextNumber(-area, area)),\n\t\t\tColor3.fromRGB(120, 120, 130),\n\t\t\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n\t\t)\n\tend\n\treturn parts\nend\n\nlocal dots = Scatter(300, 40)\nlocal buckets = {}\n\nfor _, dot in dots do\n\tlocal key = CellKey(dot.Position)\n\tbuckets[key] = buckets[key] or {}\n\ttable.insert(buckets[key], dot)\nend\n\nlocal litDots = {}","runtime":"runService.Heartbeat:Connect(function()\n\tfor _, dot in litDots do\n\t\tdot.Color = Color3.fromRGB(120, 120, 130)\n\tend\n\ttable.clear(litDots)\n\tlocal root = GetNearestRoot(ORIGIN)\n\tif not root then return end\n\tlocal center = root.Position\n\tfor cellX = math.floor((center.X - _radius) / _cell), math.floor((center.X + _radius) / _cell) do\n\t\tfor cellZ = math.floor((center.Z - _radius) / _cell), math.floor((center.Z + _radius) / _cell) do\n\t\t\tfor _, dot in buckets[cellX .. \",\" .. cellZ] or {} do\n\t\t\t\tif (dot.Position - center).Magnitude <= _radius then\n\t\t\t\t\tdot.Color = Color3.fromRGB(226, 133, 26)\n\t\t\t\t\ttable.insert(litDots, dot)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\nend)"},
"sp-quadtree":{"k":"S","what":"Builds a quadtree over 200 clumped points (splitting any square with more than 4 points) and draws the squares as outlines.","services":[],"variables":"","functions":"local function Outline(x, z, size)\n\tfor _, edge in\n\t\t{\n\t\t\t{ Vector3.new(size, 0.2, 0.2), Vector3.new(size / 2, 0, 0) },\n\t\t\t{ Vector3.new(size, 0.2, 0.2), Vector3.new(size / 2, 0, size) },\n\t\t\t{ Vector3.new(0.2, 0.2, size), Vector3.new(0, 0, size / 2) },\n\t\t\t{ Vector3.new(0.2, 0.2, size), Vector3.new(size, 0, size / 2) },\n\t\t}\n\tdo\n\t\tMakePart(\n\t\t\tedge[1],\n\t\t\tORIGIN + Vector3.new(x, 0.1, z) + edge[2],\n\t\t\tColor3.fromRGB(226, 133, 26),\n\t\t\t{ CanCollide = false }\n\t\t)\n\tend\nend\n\nlocal function Build(cellPoints, x, z, size, depth)\n\tOutline(x, z, size)\n\tif #cellPoints <= 4 or depth >= 6 then return end\n\tlocal half = size / 2\n\tfor _, quadrant in { { 0, 0 }, { half, 0 }, { 0, half }, { half, half } } do\n\t\tlocal inside = {}\n\t\tfor _, point in cellPoints do\n\t\t\tif\n\t\t\t\tpoint.X >= x + quadrant[1]\n\t\t\t\tand point.X < x + quadrant[1] + half\n\t\t\t\tand point.Y >= z + quadrant[2]\n\t\t\t\tand point.Y < z + quadrant[2] + half\n\t\t\tthen\n\t\t\t\ttable.insert(inside, point)\n\t\t\tend\n\t\tend\n\t\tBuild(inside, x + quadrant[1], z + quadrant[2], half, depth + 1)\n\tend\nend","setup":"local random = Random.new(5)\nlocal points = {}\nlocal centers = { Vector2.new(-15, -10), Vector2.new(12, 10), Vector2.new(15, -14) }\n\nfor i = 1, 200 do\n\tlocal center = centers[i % 3 + 1]\n\tlocal angle, distance = random:NextNumber(0, 2 * math.pi), random:NextNumber() ^ 2 * 8\n\tpoints[i] = Vector2.new(\n\t\tmath.clamp(center.X + math.cos(angle) * distance, -24.9, 24.9),\n\t\tmath.clamp(center.Y + math.sin(angle) * distance, -24.9, 24.9)\n\t)\n\tMakePart(\n\t\tVector3.new(0.4, 0.4, 0.4),\n\t\tORIGIN + Vector3.new(points[i].X, 0.4, points[i].Y),\n\t\tColor3.fromRGB(18, 147, 154),\n\t\t{ CanCollide = false }\n\t)\nend\n\nBuild(points, -25, -25, 50, 0)","runtime":""},
"sp-octree":{"k":"S","what":"Builds an octree over 150 points in a 3D shell and draws each cube that holds more than 4 points as see-through boxes.","services":[],"variables":"","functions":"local function Build(cellPoints, corner, size, depth)\n\tif #cellPoints <= 4 or depth >= 4 then return end\n\tMakePart(\n\t\tVector3.new(size, size, size),\n\t\tORIGIN + corner + Vector3.new(size, size, size) / 2,\n\t\tColor3.fromRGB(226, 133, 26),\n\t\t{ Transparency = 0.9, CanCollide = false }\n\t)\n\tlocal half = size / 2\n\tfor _, offsetX in { 0, half } do\n\t\tfor _, offsetY in { 0, half } do\n\t\t\tfor _, offsetZ in { 0, half } do\n\t\t\t\tlocal childCorner = corner + Vector3.new(offsetX, offsetY, offsetZ)\n\t\t\t\tlocal inside = {}\n\t\t\t\tfor _, point in cellPoints do\n\t\t\t\t\tif\n\t\t\t\t\t\tpoint.X >= childCorner.X\n\t\t\t\t\t\tand point.X < childCorner.X + half\n\t\t\t\t\t\tand point.Y >= childCorner.Y\n\t\t\t\t\t\tand point.Y < childCorner.Y + half\n\t\t\t\t\t\tand point.Z >= childCorner.Z\n\t\t\t\t\t\tand point.Z < childCorner.Z + half\n\t\t\t\t\tthen\n\t\t\t\t\t\ttable.insert(inside, point)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\t\tBuild(inside, childCorner, half, depth + 1)\n\t\t\tend\n\t\tend\n\tend\nend","setup":"local random = Random.new(19)\nlocal points = {}\n\nfor i = 1, 150 do\n\tlocal direction =\n\t\tVector3.new(random:NextNumber(-1, 1), random:NextNumber(-1, 1), random:NextNumber(-1, 1)).Unit\n\tpoints[i] = Vector3.new(0, 10, 0) + direction * random:NextNumber(6, 9)\n\tMakePart(\n\t\tVector3.new(0.4, 0.4, 0.4),\n\t\tORIGIN + points[i],\n\t\tColor3.fromRGB(18, 147, 154),\n\t\t{ CanCollide = false }\n\t)\nend\n\nBuild(points, Vector3.new(-10, 0, -10), 20, 0)","runtime":""},
"sp-nearest":{"k":"S","what":"Finds the dot nearest to you each frame by searching grid rings outward and stopping once the next ring is further than the best found. A beam points to it.","services":[],"variables":"local _cell = 6","functions":"local function CellOf(position)\n\treturn math.floor(position.X / _cell), math.floor(position.Z / _cell)\nend","setup":"local random = Random.new()\n\nlocal function Scatter(count, area)\n\tlocal parts = {}\n\tfor i = 1, count do\n\t\tparts[i] = MakePart(\n\t\t\tVector3.new(0.8, 0.8, 0.8),\n\t\t\tORIGIN + Vector3.new(random:NextNumber(-area, area), 1, random:NextNumber(-area, area)),\n\t\t\tColor3.fromRGB(120, 120, 130),\n\t\t\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n\t\t)\n\tend\n\treturn parts\nend\n\nlocal dots = Scatter(250, 40)\nlocal buckets = {}\n\nfor _, dot in dots do\n\tlocal cellX, cellZ = CellOf(dot.Position)\n\tlocal key = cellX .. \",\" .. cellZ\n\tbuckets[key] = buckets[key] or {}\n\ttable.insert(buckets[key], dot)\nend\n\nlocal beam = MakeLinePart()","runtime":"runService.Heartbeat:Connect(function()\n\tlocal root = GetNearestRoot(ORIGIN)\n\tif not root then return end\n\tlocal position = root.Position\n\tlocal playerCellX, playerCellZ = CellOf(position)\n\tlocal best, bestDistance = nil, math.huge\n\tfor ring = 0, 15 do\n\t\tif best and (ring - 1) * _cell > bestDistance then break end\n\t\tfor offsetX = -ring, ring do\n\t\t\tfor offsetZ = -ring, ring do\n\t\t\t\tif math.max(math.abs(offsetX), math.abs(offsetZ)) == ring then\n\t\t\t\t\tfor _, dot in buckets[(playerCellX + offsetX) .. \",\" .. (playerCellZ + offsetZ)] or {} do\n\t\t\t\t\t\tlocal distance = (dot.Position - position).Magnitude\n\t\t\t\t\t\tif distance < bestDistance then\n\t\t\t\t\t\t\tbest, bestDistance = dot, distance\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\tif best then DrawLine(beam, position, best.Position) end\nend)"},
"sp-sweep":{"k":"S","what":"Sweep and prune: 40 boxes sorted by their left edge; only boxes whose X ranges overlap are tested, and touching pairs turn red.","services":[],"variables":"","functions":"","setup":"local random = Random.new(6)\nlocal boxes = {}\n\nfor i = 1, 40 do\n\tlocal size = Vector3.new(random:NextNumber(1.5, 4), 1, random:NextNumber(1.5, 4))\n\tlocal part = MakePart(\n\t\tsize,\n\t\tORIGIN + Vector3.new(random:NextNumber(-20, 20), 0.5, random:NextNumber(-12, 12)),\n\t\tColor3.fromRGB(18, 147, 154),\n\t\t{ Transparency = 0.3 }\n\t)\n\ttable.insert(boxes, {\n\t\tPart = part,\n\t\tMinX = part.Position.X - size.X / 2,\n\t\tMaxX = part.Position.X + size.X / 2,\n\t\tMinZ = part.Position.Z - size.Z / 2,\n\t\tMaxZ = part.Position.Z + size.Z / 2,\n\t})\nend\n\ntable.sort(boxes, function(first, second)\n\treturn first.MinX < second.MinX\nend)\n\nlocal active, tests, hits = {}, 0, 0\n\nfor _, box in boxes do\n\tfor i = #active, 1, -1 do\n\t\tif active[i].MaxX < box.MinX then table.remove(active, i) end\n\tend\n\tfor _, other in active do\n\t\ttests += 1\n\t\tif box.MinZ <= other.MaxZ and other.MinZ <= box.MaxZ then\n\t\t\thits += 1\n\t\t\tbox.Part.Color = Color3.fromRGB(230, 60, 60)\n\t\t\tother.Part.Color = Color3.fromRGB(230, 60, 60)\n\t\tend\n\tend\n\ttable.insert(active, box)\nend\n\nprint(string.format(\"%d tests instead of %d, %d overlapping pairs\", tests, 40 * 39 / 2, hits))","runtime":""},
"sp-lod":{"k":"S","what":"150 spinning gems: ones near a player spin every frame, mid-range ones every 4th frame (staggered), far ones not at all.","services":[],"variables":"local _nearSquared = 15 ^ 2\nlocal _farSquared = 35 ^ 2","functions":"","setup":"local random = Random.new()\n\nlocal function Scatter(count, area)\n\tlocal parts = {}\n\tfor i = 1, count do\n\t\tparts[i] = MakePart(\n\t\t\tVector3.new(0.8, 0.8, 0.8),\n\t\t\tORIGIN + Vector3.new(random:NextNumber(-area, area), 1, random:NextNumber(-area, area)),\n\t\t\tColor3.fromRGB(120, 120, 130),\n\t\t\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n\t\t)\n\tend\n\treturn parts\nend\n\nlocal gems = Scatter(150, 50)\nlocal frame = 0","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tframe += 1\n\tlocal root = GetNearestRoot(ORIGIN)\n\tif not root then return end\n\tfor i, gem in gems do\n\t\tlocal offset = gem.Position - root.Position\n\t\tlocal distanceSquared = offset:Dot(offset) -- squared distance: no square root\n\t\tif distanceSquared < _nearSquared then\n\t\t\tgem.Color = Color3.fromRGB(226, 133, 26)\n\t\t\tgem.CFrame *= CFrame.Angles(0, deltaTime * 3, 0)\n\t\telseif distanceSquared < _farSquared then\n\t\t\tgem.Color = Color3.fromRGB(18, 147, 154)\n\t\t\tif (frame + i) % 4 == 0 then\n\t\t\t\tgem.CFrame *= CFrame.Angles(0, deltaTime * 12, 0)\n\t\t\tend\n\t\telse\n\t\t\tgem.Color = Color3.fromRGB(120, 120, 130)\n\t\tend\n\tend\nend)"},
"sg-movingavg":{"k":"L","what":"An FPS counter in the corner that averages the last 30 frames so it doesn't flicker.","services":[],"variables":"","functions":"","setup":"local gui = Instance.new(\"ScreenGui\")\ngui.ResetOnSpawn = false\ngui.Parent = player:WaitForChild(\"PlayerGui\")\nlocal label = Instance.new(\"TextLabel\")\nlabel.Size = UDim2.fromOffset(160, 32)\nlabel.Position = UDim2.new(1, -170, 0, 10)\nlabel.BackgroundColor3 = Color3.fromRGB(20, 20, 25)\nlabel.TextColor3 = Color3.new(1, 1, 1)\nlabel.TextScaled = true\nlabel.Parent = gui\nlocal WINDOW, samples, sum = 30, {}, 0","runtime":"runService.RenderStepped:Connect(function(deltaTime)\n\ttable.insert(samples, deltaTime)\n\tsum += deltaTime\n\tif #samples > WINDOW then\n\t\tsum -= table.remove(samples, 1)\n\tend\n\tlabel.Text = string.format(\"%.0f FPS (avg)\", #samples / sum)\nend)"},
"sg-ema":{"k":"S","what":"A needle follows a noisy signal smoothly using exponential smoothing: smoothed += (raw − smoothed) × alpha.","services":[],"variables":"","functions":"","setup":"local raw =\n\tMakePart(Vector3.new(0.6, 0.6, 0.6), ORIGIN, Color3.fromRGB(120, 120, 130), { CanCollide = false })\n\nlocal smooth =\n\tMakePart(Vector3.new(1.2, 1.2, 1.2), ORIGIN, Color3.fromRGB(226, 133, 26), { CanCollide = false })\n\nMakeLabel(raw, \"raw\")\nMakeLabel(smooth, \"smoothed\")\nlocal value = 0","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tlocal now = os.clock()\n\tlocal noisy = 4 * math.sin(now * 0.8) + (math.random() - 0.5) * 3\n\tvalue += (noisy - value) * (1 - math.exp(-deltaTime / 0.3)) -- about 0.3 s reaction time\n\traw.Position = ORIGIN + Vector3.new(-3, 6 + noisy, 0)\n\tsmooth.Position = ORIGIN + Vector3.new(3, 6 + value, 0)\nend)"},
"sg-deadzone":{"k":"L","what":"Shows your gamepad left stick (or WASD) as a dot: tiny input inside the dead zone is ignored and the rest is rescaled and curved.","services":["UserInputService"],"variables":"local _deadZone = 0.2\nlocal _curvePower = 2","functions":"","setup":"local gui = Instance.new(\"ScreenGui\")\ngui.ResetOnSpawn = false\ngui.Parent = player:WaitForChild(\"PlayerGui\")\nlocal pad = Instance.new(\"Frame\")\npad.Size = UDim2.fromOffset(160, 160)\npad.Position = UDim2.new(0, 20, 1, -180)\npad.BackgroundColor3 = Color3.fromRGB(30, 30, 35)\npad.Parent = gui\nlocal dot = Instance.new(\"Frame\")\ndot.AnchorPoint = Vector2.new(0.5, 0.5)\ndot.Size = UDim2.fromOffset(16, 16)\ndot.BackgroundColor3 = Color3.fromRGB(226, 133, 26)\ndot.Parent = pad\nlocal stick = Vector2.zero","runtime":"userInputService.InputChanged:Connect(function(input)\n\tif input.KeyCode == Enum.KeyCode.Thumbstick1 then\n\t\tstick = Vector2.new(input.Position.X, -input.Position.Y)\n\tend\nend)\n\nlocal function Shape(stickVector)\n\tlocal magnitude = math.min(stickVector.Magnitude, 1)\n\tif magnitude <= _deadZone then return Vector2.zero end\n\treturn stickVector.Unit * ((magnitude - _deadZone) / (1 - _deadZone)) ^ _curvePower\nend\n\nrunService.RenderStepped:Connect(function()\n\tlocal keys = Vector2.new(\n\t\t(userInputService:IsKeyDown(Enum.KeyCode.D) and 1 or 0)\n\t\t\t- (userInputService:IsKeyDown(Enum.KeyCode.A) and 1 or 0),\n\t\t(userInputService:IsKeyDown(Enum.KeyCode.S) and 1 or 0)\n\t\t\t- (userInputService:IsKeyDown(Enum.KeyCode.W) and 1 or 0)\n\t)\n\tlocal shaped = Shape(stick.Magnitude > 0.01 and stick or keys)\n\tdot.Position = UDim2.fromScale(0.5 + shaped.X * 0.45, 0.5 + shaped.Y * 0.45)\nend)"},
"sg-shake":{"k":"L","what":"Press E for camera shake: trauma rises on each press and drains over time; the shake is trauma² × noise.","services":["UserInputService"],"variables":"","functions":"","setup":"local trauma = 0","runtime":"userInputService.InputBegan:Connect(function(input, processed)\n\tif not processed and input.KeyCode == Enum.KeyCode.E then trauma = math.min(1, trauma + 0.5) end\nend)\n\nrunService:BindToRenderStep(\"Shake\", Enum.RenderPriority.Camera.Value + 1, function(deltaTime)\n\ttrauma = math.max(0, trauma - 1.2 * deltaTime)\n\tif trauma <= 0 then return end\n\tlocal shake, noiseTime = trauma * trauma, os.clock() * 15\n\tlocal offset = Vector3.new(math.noise(noiseTime, 1.3), math.noise(noiseTime, 7.1), 0) * 2.4 * shake\n\tcamera.CFrame = camera.CFrame\n\t\t* CFrame.new(offset)\n\t\t* CFrame.Angles(0, 0, math.noise(noiseTime, 3.3) * 0.14 * shake)\nend)"},
"sg-alias":{"k":"S","what":"A wheel with 8 spokes spins faster and faster. Watch it on screen: at some speeds it looks frozen or spinning backwards (aliasing).","services":[],"variables":"","functions":"","setup":"local wheel = MakePart(\n\tVector3.new(0.4, 8, 8),\n\tORIGIN + Vector3.new(0, 5, 0),\n\tColor3.fromRGB(60, 60, 70),\n\t{ Shape = Enum.PartType.Cylinder, CanCollide = false }\n)\n\nlocal spokes = {}\n\nfor i = 1, 4 do\n\tspokes[i] = MakePart(\n\t\tVector3.new(0.5, 7.6, 0.4),\n\t\twheel.Position,\n\t\tColor3.fromRGB(226, 133, 26),\n\t\t{ CanCollide = false }\n\t)\nend\n\nlocal label = MakeLabel(wheel)\nlocal angle = 0","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tlocal turnsPerSecond = (os.clock() % 30) * 0.5 -- slowly speeds up, then resets\n\tangle += turnsPerSecond * 2 * math.pi * deltaTime\n\tfor i, spoke in spokes do\n\t\tspoke.CFrame = CFrame.new(wheel.Position) * CFrame.Angles(angle + i * math.pi / 4, 0, 0)\n\tend\n\tlabel.Text = string.format(\"%.1f turns per second\", turnsPerSecond)\nend)"},
"sg-interp":{"k":"S","what":"The server sends a moving target's position only 5 times a second. One copy snaps to each update; the other renders 0.3 s in the past and interpolates smoothly.","services":[],"variables":"","functions":"local function TruePositionAt(atTime)\n\treturn ORIGIN + Vector3.new(math.sin(atTime * 0.9) * 12, 3, math.sin(atTime * 1.8) * 6)\nend","setup":"local real = MakePart(\n\tVector3.new(1.5, 1.5, 1.5),\n\tORIGIN,\n\tColor3.fromRGB(163, 162, 165),\n\t{ Transparency = 0.6, CanCollide = false }\n)\n\nlocal snapped =\n\tMakePart(Vector3.new(1.5, 1.5, 1.5), ORIGIN, Color3.fromRGB(230, 60, 60), { CanCollide = false })\n\nlocal smooth =\n\tMakePart(Vector3.new(1.5, 1.5, 1.5), ORIGIN, Color3.fromRGB(226, 133, 26), { CanCollide = false })\n\nMakeLabel(snapped, \"snap\")\nMakeLabel(smooth, \"interpolated\")\nlocal buffer, RENDER_DELAY, UPDATES_PER_SECOND = {}, 0.3, 5","runtime":"task.spawn(function()\n\twhile true do\n\t\ttable.insert(buffer, { Time = os.clock(), Position = TruePositionAt(os.clock()) }) -- \"network update\"\n\t\tif #buffer > 20 then table.remove(buffer, 1) end\n\t\tsnapped.Position = buffer[#buffer].Pos + Vector3.new(0, 2, 0)\n\t\ttask.wait(1 / UPDATES_PER_SECOND)\n\tend\nend)\n\nrunService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\treal.Position = TruePositionAt(now)\n\tlocal renderTime = now - RENDER_DELAY\n\tfor i = #buffer, 2, -1 do\n\t\tlocal older, newer = buffer[i - 1], buffer[i]\n\t\tif older.Time <= renderTime and renderTime <= newer.Time then\n\t\t\tsmooth.Position = older.Position:Lerp(\n\t\t\t\tnewer.Position,\n\t\t\t\t(renderTime - older.Time) / (newer.Time - older.Time)\n\t\t\t) + Vector3.new(0, 4, 0)\n\t\t\tbreak\n\t\tend\n\tend\nend)"},
"sg-extrap":{"k":"S","what":"With only 4 updates a second, a copy predicts where the target is now from its last position and velocity (dead reckoning), blending smoothly to corrections.","services":[],"variables":"","functions":"local function TruePositionAt(atTime)\n\treturn ORIGIN + Vector3.new(math.sin(atTime * 0.9) * 12, 3, math.sin(atTime * 1.8) * 6)\nend","setup":"local real = MakePart(\n\tVector3.new(1.5, 1.5, 1.5),\n\tORIGIN,\n\tColor3.fromRGB(163, 162, 165),\n\t{ Transparency = 0.6, CanCollide = false }\n)\n\nlocal predicted =\n\tMakePart(Vector3.new(1.5, 1.5, 1.5), ORIGIN, Color3.fromRGB(226, 133, 26), { CanCollide = false })\n\nMakeLabel(predicted, \"predicted\")\nlocal last = { Time = os.clock(), Position = TruePositionAt(os.clock()), Velocity = Vector3.zero }","runtime":"task.spawn(function()\n\twhile true do\n\t\tlocal atTime = os.clock()\n\t\tlast = {\n\t\t\tTime = atTime,\n\t\t\tPosition = TruePositionAt(atTime),\n\t\t\tVelocity = (TruePositionAt(atTime + 0.01) - TruePositionAt(atTime)) / 0.01,\n\t\t}\n\t\ttask.wait(0.25)\n\tend\nend)\n\nlocal shown = last.Position\n\nrunService.Heartbeat:Connect(function(deltaTime)\n\tlocal now = os.clock()\n\treal.Position = TruePositionAt(now)\n\tlocal guess = last.Position + last.Velocity * (now - last.Time)\n\tshown = shown:Lerp(guess, 1 - math.exp(-8 * deltaTime))\n\tpredicted.Position = shown\nend)"},
"sg-hysteresis":{"k":"S","what":"An NPC starts chasing when you come within 10 studs and only gives up past 16, so it doesn't flicker at the edge.","services":[],"variables":"local _startChase = 10\nlocal _stopChase = 16","functions":"","setup":"local npc = MakePart(Vector3.new(2, 4, 2), ORIGIN + Vector3.new(0, 2, 0), Color3.fromRGB(90, 160, 230))\nlocal label = MakeLabel(npc)\nlocal home = npc.Position\nlocal chasing = false","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tlocal root = GetNearestRoot(npc.Position)\n\tlocal distance = root and (root.Position - npc.Position).Magnitude or math.huge\n\tif not chasing and distance < _startChase then\n\t\tchasing = true\n\telseif chasing and distance > _stopChase then\n\t\tchasing = false\n\tend\n\tlocal goal = chasing and root and root.Position * Vector3.new(1, 0, 1) + Vector3.new(0, 2, 0) or home\n\tlocal offset = goal - npc.Position\n\tif offset.Magnitude > 0.1 then\n\t\tnpc.Position += offset.Unit * math.min(8 * deltaTime, offset.Magnitude)\n\tend\n\tnpc.Color = chasing and Color3.fromRGB(230, 60, 60) or Color3.fromRGB(90, 160, 230)\n\tlabel.Text = string.format(\"%s (%.0f studs)\", chasing and \"CHASING\" or \"idle\", distance)\nend)"},
"sg-ratelimit":{"k":"S","what":"A button anyone can click, protected by a token bucket per player: bursts of 3, then 1 per second. Spam clicks are rejected.","services":[],"variables":"local _capacity = 3\nlocal _refillPerSecond = 1","functions":"","setup":"local buckets = {}\nlocal button = MakePart(Vector3.new(4, 1, 4), ORIGIN + Vector3.new(0, 0.5, 0), Color3.fromRGB(226, 133, 26))\nlocal label = MakeLabel(button, \"click fast!\")\nlocal clickDetector = Instance.new(\"ClickDetector\")\nclickDetector.Parent = button","runtime":"clickDetector.MouseClick:Connect(function(player)\n\tlocal now = os.clock()\n\tlocal bucket = buckets[player] or { Tokens = _capacity, Last = now }\n\tbuckets[player] = bucket\n\tbucket.Tokens = math.min(_capacity, bucket.Tokens + (now - bucket.Last) * _refillPerSecond)\n\tbucket.Last = now\n\tif bucket.Tokens < 1 then\n\t\tlabel.Text = player.Name .. \": too fast (rejected)\"\n\t\tbutton.Color = Color3.fromRGB(230, 60, 60)\n\t\treturn\n\tend\n\tbucket.Tokens -= 1\n\tlabel.Text = string.format(\"%s: accepted (%.1f tokens left)\", player.Name, bucket.Tokens)\n\tbutton.Color = Color3.fromRGB(60, 200, 90)\nend)\n\nplayers.PlayerRemoving:Connect(function(player)\n\tbuckets[player] = nil\nend)"}
});
})();
